INSERT INTO `ai_generations` VALUES (1,1,3,'course_plan','course_plan','{\"subject\":\"Database Management Systems\",\"credits\":\"4\",\"university\":\"Autonomous\",\"template\":\"standard\",\"provider\":\"gemini\"}','{\"title\":\"Database Management Systems\",\"learning_outcomes\":[\"CO1: Understand and explain fundamental database concepts, architecture, and conceptual modeling using ER\\/EER diagrams (Bloom Level: K2).\",\"CO2: Apply relational algebra, tuple calculus, and SQL to write optimized queries for complex data retrieval and manipulation (Bloom Level: K3).\",\"CO3: Analyze relational database schemas and apply normalization techniques (1NF to BCNF\\/4NF) to eliminate anomalies (Bloom Level: K4).\",\"CO4: Evaluate transaction processing, concurrency control mechanisms, and crash recovery algorithms to ensure ACID properties (Bloom Level: K4).\",\"CO5: Design and implement physical storage organizations, indexing structures (B\\/B+ Trees), and analyze query execution plans alongside modern NoSQL architectures (Bloom Level: K5).\"],\"units\":[{\"unit_number\":1,\"title\":\"Introduction to DBMS and Conceptual Data Modeling\",\"hours\":10,\"topics\":[\"Data vs Information, Database System Concepts and Architecture\",\"Three-Schema Architecture and Data Independence\",\"Database Languages, Interfaces, and Overall System Structure\",\"Data Models: Hierarchical, Network, and Relational Foundations\",\"Entity-Relationship (ER) Modeling: Entities, Attributes, Relationships, Constraints\",\"Extended ER (EER) Modeling: Specialization, Generalization, and Categorization\",\"Mapping ER\\/EER Diagrams to Relational Schemas\"],\"outcomes\":[\"Illustrate the role of DBMS components and 3-schema architecture in abstraction.\",\"Construct comprehensive ER and EER diagrams for real-world enterprise applications.\",\"Transform conceptual ER schemas into normalized relational schemas.\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"Interactive Lecture\",\"Flipped Classroom\",\"Case-based Problem Solving (Enterprise Scenario Modeling)\"],\"assessment\":[\"Continuous Internal Assessment (CIA-1) Quiz\",\"ER Diagram Modeling Assignment on an Industry Case Study\",\"Formative Tutorial Worksheets\"]},{\"unit_number\":2,\"title\":\"Relational Model, Formal Languages, and Advanced SQL\",\"hours\":11,\"topics\":[\"Relational Model Concepts, Integrity Constraints (Domain, Key, Referential, Operational)\",\"Formal Relational Query Languages: Relational Algebra (Fundamental and Extended Operations)\",\"Tuple Relational Calculus and Domain Relational Calculus\",\"SQL Fundamentals: DDL, DML, DCL, and TCL Commands\",\"Complex SQL Queries: Nested Subqueries, Correlated Queries, Set Operations, Group By, Having\",\"Views, Materialized Views, Assertions, and Triggers\",\"Stored Procedures, Functions, and Embedded SQL\\/Cursor Management\"],\"outcomes\":[\"Formulate relational algebraic expressions for procedural data retrieval.\",\"Develop complex, performant SQL queries using nested subqueries, joins, and aggregates.\",\"Implement declarative integrity rules, triggers, and stored routines to automate business logic.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Live Coding Demonstrations\",\"Collaborative Lab Sprints\",\"Think-Pair-Share on Query Optimization\"],\"assessment\":[\"Hands-on SQL Coding Lab Exam (PostgreSQL\\/MySQL)\",\"Mid-Term Test Problem on Relational Algebra\",\"Peer-reviewed Database Scripting Assignment\"]},{\"unit_number\":3,\"title\":\"Relational Database Design and Normalization Theory\",\"hours\":10,\"topics\":[\"Informal Design Guidelines for Relation Schemas and Data Redundancy Pitfalls\",\"Functional Dependencies (FDs): Definition, Trivial\\/Non-trivial, Closure of FDs\",\"Armstrong\'s Axioms and Canonical Minimal Cover Algorithm\",\"Normal Forms based on Primary Keys: 1NF, 2NF, 3NF\",\"Boyce-Codd Normal Form (BCNF): Decomposition, Testing, and Limitations\",\"Lossless Join Decomposition and Dependency Preservation Properties\",\"Multi-valued Dependencies and 4NF; Join Dependencies and 5NF Overview\"],\"outcomes\":[\"Compute closure of attribute sets and derive minimal canonical covers of functional dependencies.\",\"Evaluate database schemas against normal form criteria (1NF through BCNF).\",\"Synthesize lossless-join and dependency-preserving decompositions for enterprise relations.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Chalk-and-Board Derivations\",\"Algorithmic Walkthroughs\",\"Guided Error-Analysis Sessions on Schema Anomalies\"],\"assessment\":[\"Class Test on Normalization & Dependency Preservation\",\"Graded Analytical Homework on Canonical Cover and BCNF Decomposition\",\"Open-Book Schema Refactoring Challenge\"]},{\"unit_number\":4,\"title\":\"Transaction Processing, Concurrency Control, and Recovery\",\"hours\":10,\"topics\":[\"Transaction Concepts: ACID Properties, Transaction States, and Concurrent Executions\",\"Schedules: Serializability, Conflict Serializability, and View Serializability\",\"Testing for Conflict Serializability using Precedence Graphs\",\"Recoverability, Cascadelessness, and Strict Schedules\",\"Concurrency Control Protocols: Lock-based (2PL, Strict 2PL, Rigorous 2PL), Deadlock Handling\",\"Timestamp-based Protocols and Thomas\' Write Rule; Multiple Granularity Locking\",\"Database Recovery Techniques: Write-Ahead Logging (WAL), Checkpointing, ARIES Recovery Algorithm\"],\"outcomes\":[\"Analyze transaction schedules for conflict serializability and recoverability.\",\"Compare locking and timestamping concurrency protocols under varied workload contentions.\",\"Design crash-recovery strategies utilizing WAL and ARIES algorithm mechanics.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Scenario-based Conflict Tracing\",\"Interactive Simulation Tools for Lock Contention\",\"Socratic Seminar on Isolation vs Performance Trade-offs\"],\"assessment\":[\"Mid-Term Exam Evaluation\",\"Serializability Precedence Graph Analytical Assignment\",\"Online Diagnostic Quiz on Deadlock Resolution Techniques\"]},{\"unit_number\":5,\"title\":\"Storage, Indexing, Query Optimization, and Modern Databases\",\"hours\":9,\"topics\":[\"Physical Storage Organization: File Organization, Record Formats, Buffer Pool Management\",\"Index Structures for Files: Primary, Secondary, Clustering Indexes\",\"Multi-level Indexing, Dynamic Multilevel Indexes using B-Trees and B+ Trees\",\"Static and Dynamic Hashing Techniques (Extendible and Linear Hashing)\",\"Query Processing Overview: Translation, Heuristic Optimization, Cost-based Estimation\",\"Modern Database Architectures: Distributed DBs, CAP Theorem, NoSQL Data Stores (Key-Value, Document, Columnar, Graph)\",\"Cloud-Native Database Systems and HTAP Engines Introduction\"],\"outcomes\":[\"Calculate storage, tree-height, and block access costs for B+ tree indexing structures.\",\"Demonstrate relational query optimization using algebraic transformation heuristics.\",\"Appraise modern NoSQL models against traditional RDBMS based on CAP theorem constraints.\"],\"bloom_k_level\":\"K5\",\"teaching_methods\":[\"Project-Based Learning (Capstone Schema Implementation)\",\"Comparative Architecture Seminar\",\"Query Execution Plan Analysis using EXPLAIN ANALYZE\"],\"assessment\":[\"End-Semester Project Submission (Full-Stack Relational\\/NoSQL Application)\",\"Technical Seminar Presentation on NoSQL vs Relational Paradigms\",\"Comprehensive End-Semester Theory & Practical Examination\"]}],\"weekly_plan\":[\"Week 1: Introduction to DBMS Architecture, 3-Schema Architecture, Data Independence, System Catalogs.\",\"Week 2: ER Modeling, Entity Types, Relationship Constraints, Cardinality Ratios, Weak Entities.\",\"Week 3: Enhanced ER (EER) Modeling, Generalization\\/Specialization, Schema mapping algorithms.\",\"Week 4: Relational Model Constraints, Relational Algebra fundamental & composite operations.\",\"Week 5: SQL DDL, DML, Complex Queries, Grouping, Aggregate operators, Nested Subqueries.\",\"Week 6: Views, Triggers, Stored Procedures, PL\\/SQL blocks, and SQL performance considerations.\",\"Week 7: Functional Dependencies, Attribute Closures, Canonical Covers, and Anomalies demonstration.\",\"Week 8: Relational Normalization: 1NF, 2NF, 3NF, and BCNF testing with decomposition rules.\",\"Week 9: Lossless Decomposition, Dependency Preservation proofs, Introduction to 4NF\\/5NF.\",\"Week 10: Transaction Management, ACID properties, Conflict and View Serializability analysis.\",\"Week 11: Concurrency Control: Two-Phase Locking (2PL), Deadlock Detection and Prevention.\",\"Week 12: Timestamp Ordering, Granularity of Data Items, Recovery concepts, WAL, and Checkpoints.\",\"Week 13: Physical File Storage, Primary, Clustering, Secondary Indexes, Static & Dynamic Hashing.\",\"Week 14: Search Trees, B-Tree and B+ Tree insert\\/delete algorithms and disk block cost modeling.\",\"Week 15: Query Processing and Optimization, Modern Distributed NoSQL architectures and CAP Theorem review.\"],\"resources\":[\"Abraham Silberschatz, Henry F. Korth, S. Sudarshan, \'Database System Concepts\', 7th Edition, McGraw-Hill, 2019.\",\"Ramez Elmasri, Shamkant B. Navathe, \'Fundamentals of Database Systems\', 7th Edition, Pearson, 2016.\",\"Raghu Ramakrishnan, Johannes Gehrke, \'Database Management Systems\', 3rd Edition, McGraw-Hill, 2003.\",\"PostgreSQL Documentation & Enterprise Execution Plan Manuals (Online Resource).\",\"NPTEL Course: Database Management System by Prof. Partha Pratim Das (IIT Kharagpur).\"],\"expert_advice\":[\"Emphasize rigorous mathematical foundations in Unit 2 (Relational Algebra) to build solid intuitions for SQL query engines.\",\"In Unit 3, avoid mechanical decomposition; mandate that students trace actual data anomalies (insertion, deletion, update) before and after normalization.\",\"Utilize EXPLAIN and EXPLAIN ANALYZE commands in PostgreSQL during Unit 5 to bridge the gap between theoretical query cost models and practical disk execution plans.\",\"Align student term projects with NBA Criterion 3 (Complex Engineering Problems) by enforcing concurrent access requirements, trigger-based audits, and foreign key cascading constraints.\"],\"bloom_distribution\":{\"K1\":5,\"K2\":15,\"K3\":30,\"K4\":35,\"K5\":15,\"K6\":0},\"ai_score\":{\"obe_compliance_rating\":0.98,\"nba_gapc_v4_alignment\":0.96,\"naac_binary_readiness\":0.97,\"rigor_index\":0.94}}','gemini-3.8-flash',NULL,NULL,138209,'success',NULL,NULL,NULL,'2026-11-11 11:48:11'),(2,1,3,'course_plan','course_plan','{\"subject\":\"Database Management Systems\",\"credits\":\"4\",\"university\":\"Autonomous\",\"template\":\"standard\",\"provider\":\"gemini\"}','{\"title\":\"Database Management Systems\",\"learning_outcomes\":[\"Understand the fundamental concepts of Database Management Systems and data models.\",\"Design entity-relationship diagrams and map them to relational database schemas.\",\"Formulate complex SQL queries using DDL, DML, DCL, and TCL commands.\",\"Apply normalization techniques to reduce data redundancy and maintain integrity.\",\"Analyze transaction management, concurrency control protocols, and recovery techniques.\"],\"units\":[{\"unit_number\":1,\"title\":\"Introduction to DBMS and ER Model\",\"hours\":12,\"topics\":[\"Database System Applications\",\"Purpose of Database Systems\",\"View of Data\",\"Data Independence\",\"Database Languages\",\"Data Models\",\"Database Architecture\",\"Entity-Relationship (ER) Model\",\"Mapping Cardinalities\",\"Keys\",\"ER Diagrams\",\"Reduction to Relational Schemas\"],\"outcomes\":[\"Explain the role of DBMS in modern enterprise applications.\",\"Construct ER diagrams for real-world scenarios.\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"Chalk and Talk\",\"PowerPoint Presentation\",\"Case Study Discussion\"],\"assessment\":[\"Quiz 1\",\"Assignment 1\",\"Internal Test 1\"]},{\"unit_number\":2,\"title\":\"Relational Model and Structured Query Language (SQL)\",\"hours\":15,\"topics\":[\"Structure of Relational Databases\",\"Fundamental Relational Algebra Operations\",\"Extended Relational Algebra Operations\",\"SQL Data Definition\",\"Basic Structure of SQL Queries\",\"Set Operations\",\"Aggregate Functions\",\"Null Values\",\"Nested Subqueries\",\"Complex Queries\",\"Views\",\"Joined Relations\"],\"outcomes\":[\"Execute relational algebra operations.\",\"Write efficient SQL queries for data retrieval and manipulation.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Interactive Lab Sessions\",\"Live SQL Coding Demonstrations\"],\"assessment\":[\"Lab Practical 1\",\"SQL Coding Assignment\",\"Internal Test 1\"]},{\"unit_number\":3,\"title\":\"Database Design and Normalization\",\"hours\":12,\"topics\":[\"Features of Good Relational Design\",\"Atomic Domains and First Normal Form\",\"Decomposition Using Functional Dependencies\",\"Functional Dependency Theory\",\"Algorithms for Functional Dependencies\",\"Closure of Set of Functional Dependencies\",\"Closure of Attribute Sets\",\"Canonical Cover\",\"Boyer-Codd Normal Form (BCNF)\",\"Third Normal Form (3NF)\",\"Fourth Normal Form (4NF)\",\"Multi-valued Dependencies\"],\"outcomes\":[\"Analyze functional dependencies and determine attribute closures.\",\"Normalize relational schemas up to BCNF.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Problem-Solving Sessions\",\"Peer Teaching\"],\"assessment\":[\"Assignment 2\",\"Quiz 2\",\"Internal Test 2\"]},{\"unit_number\":4,\"title\":\"Transactions and Concurrency Control\",\"hours\":11,\"topics\":[\"Transaction Concept\",\"Simple Transaction Model\",\"Storage Structure\",\"Transaction Atomicity and Durability\",\"Transaction Isolation\",\"Serializability\",\"Recoverable Schedules\",\"Cascadeless Schedules\",\"Concurrency Control\",\"Lock-Based Protocols\",\"Timestamp-Based Protocols\",\"Validation-Based Protocols\",\"Deadlock Handling\"],\"outcomes\":[\"Verify the serializability of transaction schedules.\",\"Compare concurrency control protocols and deadlock management techniques.\"],\"bloom_k_level\":\"K5\",\"teaching_methods\":[\"Lecture\",\"Simulations\",\"Case Study Analysis\"],\"assessment\":[\"Assignment 3\",\"Internal Test 2\",\"End Semester Exam\"]},{\"unit_number\":5,\"title\":\"Recovery System and Advanced Databases\",\"hours\":10,\"topics\":[\"Failure Classification\",\"Storage\",\"Recovery and Atomicity\",\"Log-Based Recovery\",\"Checkpoints\",\"Shadow Paging\",\"Recovery with Concurrent Transactions\",\"Introduction to NoSQL Databases\",\"CAP Theorem\",\"Introduction to Distributed Databases\"],\"outcomes\":[\"Explain log-based recovery and checkpointing mechanisms.\",\"Compare traditional RDBMS with NoSQL and distributed databases.\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"Flipped Classroom\",\"Technical Seminar\"],\"assessment\":[\"Quiz 3\",\"End Semester Exam\"]}],\"weekly_plan\":[\"Week 1: Introduction to Database System Applications and Architecture\",\"Week 2: ER Modeling, Mapping Cardinalities, and ER Diagrams\",\"Week 3: Reduction of ER to Relational Schemas and Relational Algebra Basics\",\"Week 4: Extended Relational Algebra Operations and Introduction to SQL\",\"Week 5: SQL DDL, DML, Basic Queries, and Aggregate Functions\",\"Week 6: Nested Subqueries, Joins, and Views in SQL\",\"Week 7: Database Design Goals, Functional Dependencies, and Attribute Closures\",\"Week 8: Normalization - 1NF, 2NF, 3NF, and BCNF\",\"Week 9: Advanced Normalization, Multi-valued Dependencies, and 4NF\",\"Week 10: Transaction Concept, ACID Properties, and Serializability\",\"Week 11: Concurrency Control - Lock-based and Timestamp-based Protocols\",\"Week 12: Deadlock Handling and Recovery System Basics\",\"Week 13: Log-based Recovery, Checkpoints, and Shadow Paging\",\"Week 14: Introduction to NoSQL Databases and CAP Theorem\",\"Week 15: Revision, Doubt Clearing, and Mock Practical Exams\"],\"resources\":[\"Silberschatz, A., Korth, H. F., & Sudarshan, S., Database System Concepts, McGraw-Hill.\",\"Elmasri, R., & Navathe, S. B., Fundamentals of Database Systems, Pearson.\",\"Ramakrishnan, R., & Gehrke, J., Database Management Systems, McGraw-Hill.\"],\"expert_advice\":[\"Emphasize hands-on SQL practice in a dedicated database lab to reinforce theoretical concepts.\",\"Use real-world database design case studies to explain normalization and functional dependencies effectively.\",\"Align continuous internal assessments with Bloom\'s taxonomy levels K1 through K5.\"],\"bloom_distribution\":{\"K1\":10,\"K2\":20,\"K3\":35,\"K4\":25,\"K5\":10,\"K6\":0},\"ai_score\":95.5}','gemini-3.5-flash-lite',NULL,NULL,9578,'success',NULL,NULL,NULL,'2026-11-11 11:59:08'),(3,1,3,'lesson','lesson','{\"plan_id\":1,\"provider\":\"gemini\"}','{\"sessions\":[{\"session_number\":1,\"title\":\"Database System Applications & Purpose\",\"duration_mins\":60,\"objectives\":[\"Explain the role of DBMS in modern enterprise applications.\",\"Understand the purpose of database systems compared to file systems.\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Discussion on real-world data management challenges.\"],\"formative_assessment\":[\"Quick Q&A session\"],\"engagement\":[\"Real-world scenario brainstorming\"]},{\"session_number\":2,\"title\":\"View of Data and Data Independence\",\"duration_mins\":60,\"objectives\":[\"Describe data abstraction levels.\",\"Differentiate between physical and logical data independence.\"],\"teaching_method\":\"PowerPoint Presentation\",\"activities\":[\"Architecture diagram walkthrough\"],\"formative_assessment\":[\"Concept check quiz\"],\"engagement\":[\"Think-pair-share\"]},{\"session_number\":3,\"title\":\"Database Languages and Data Models\",\"duration_mins\":60,\"objectives\":[\"Identify DDL and DML commands.\",\"Compare different data models.\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Categorizing database language statements\"],\"formative_assessment\":[\"Short written check\"],\"engagement\":[\"Interactive board work\"]},{\"session_number\":4,\"title\":\"Database Architecture\",\"duration_mins\":60,\"objectives\":[\"Understand 2-tier and 3-tier client-server architectures.\"],\"teaching_method\":\"PowerPoint Presentation\",\"activities\":[\"Drawing architectural layers\"],\"formative_assessment\":[\"Labeling diagram exercise\"],\"engagement\":[\"Group discussion\"]},{\"session_number\":5,\"title\":\"Introduction to Entity-Relationship (ER) Model\",\"duration_mins\":60,\"objectives\":[\"Define entities, attributes, and relationships.\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Identifying entities from a mini-case study\"],\"formative_assessment\":[\"Quiz 1\"],\"engagement\":[\"Live sketching on board\"]},{\"session_number\":6,\"title\":\"Mapping Cardinalities and Keys\",\"duration_mins\":60,\"objectives\":[\"Determine mapping cardinalities (1:1, 1:N, N:M).\",\"Identify primary, candidate, and foreign keys.\"],\"teaching_method\":\"Case Study Discussion\",\"activities\":[\"Key identification exercise\"],\"formative_assessment\":[\"Assignment 1 distribution and review\"],\"engagement\":[\"Peer review of keys\"]},{\"session_number\":7,\"title\":\"ER Diagrams - Part 1\",\"duration_mins\":60,\"objectives\":[\"Construct ER diagrams for simple scenarios.\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Step-by-step ER diagram construction\"],\"formative_assessment\":[\"In-class drawing check\"],\"engagement\":[\"Collaborative whiteboard\"]},{\"session_number\":8,\"title\":\"ER Diagrams - Part 2\",\"duration_mins\":60,\"objectives\":[\"Handle complex relationships and weak entities in ER diagrams.\"],\"teaching_method\":\"Case Study Discussion\",\"activities\":[\"University database schema design\"],\"formative_assessment\":[\"Design critique\"],\"engagement\":[\"Small group design challenge\"]},{\"session_number\":9,\"title\":\"Reduction of ER Schemas to Relational Schemas - Part 1\",\"duration_mins\":60,\"objectives\":[\"Map strong and weak entity sets to tables.\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Translation exercise from ER to relational tables\"],\"formative_assessment\":[\"Schema verification check\"],\"engagement\":[\"Guided practice\"]},{\"session_number\":10,\"title\":\"Reduction of ER Schemas to Relational Schemas - Part 2\",\"duration_mins\":60,\"objectives\":[\"Map relationship sets and multivalued attributes.\"],\"teaching_method\":\"PowerPoint Presentation\",\"activities\":[\"Mapping N:M relationships\"],\"formative_assessment\":[\"Internal Test 1 preparation quiz\"],\"engagement\":[\"Q&A session\"]},{\"session_number\":11,\"title\":\"Unit 1 Review and Problem Solving\",\"duration_mins\":60,\"objectives\":[\"Review concepts from Unit 1.\",\"Solve comprehensive ER modeling problems.\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Solving past exam questions\"],\"formative_assessment\":[\"Internal Test 1\"],\"engagement\":[\"Competitive quiz\"]},{\"session_number\":12,\"title\":\"Unit 1 Wrap-up & Conceptual Clearance\",\"duration_mins\":60,\"objectives\":[\"Address doubts from Internal Test 1.\"],\"teaching_method\":\"Case Study Discussion\",\"activities\":[\"Test debrief and paper review\"],\"formative_assessment\":[\"Self-assessment rubric\"],\"engagement\":[\"Open forum discussion\"]},{\"session_number\":13,\"title\":\"Structure of Relational Databases\",\"duration_mins\":60,\"objectives\":[\"Understand relational model concepts and integrity constraints.\"],\"teaching_method\":\"Interactive Lab Sessions\",\"activities\":[\"Exploring table structures\"],\"formative_assessment\":[\"Lab check\"],\"engagement\":[\"Hands-on terminal work\"]},{\"session_number\":14,\"title\":\"Fundamental Relational Algebra Operations\",\"duration_mins\":60,\"objectives\":[\"Execute Select, Project, Union, Set Difference, and Cartesian Product.\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Writing relational algebra expressions\"],\"formative_assessment\":[\"Worksheet evaluation\"],\"engagement\":[\"Board problem solving\"]},{\"session_number\":15,\"title\":\"Extended Relational Algebra Operations\",\"duration_mins\":60,\"objectives\":[\"Apply Join, Division, and Assignment operations.\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Complex relational algebra derivation\"],\"formative_assessment\":[\"Pop quiz\"],\"engagement\":[\"Pair programming equivalent logic\"]},{\"session_number\":16,\"title\":\"SQL Data Definition and Basic Queries\",\"duration_mins\":60,\"objectives\":[\"Use DDL commands to create databases and tables.\",\"Write basic SELECT-FROM-WHERE queries.\"],\"teaching_method\":\"Live SQL Coding Demonstrations\",\"activities\":[\"Creating tables in SQL environment\"],\"formative_assessment\":[\"Lab Practical 1\"],\"engagement\":[\"Live coding along with instructor\"]},{\"session_number\":17,\"title\":\"SQL Set Operations and Aggregate Functions\",\"duration_mins\":60,\"objectives\":[\"Use UNION, INTERSECT, EXCEPT.\",\"Apply COUNT, SUM, AVG, MAX, MIN with GROUP BY and HAVING.\"],\"teaching_method\":\"Interactive Lab Sessions\",\"activities\":[\"Writing aggregation queries\"],\"formative_assessment\":[\"SQL Coding Assignment task 1\"],\"engagement\":[\"Troubleshooting syntax errors in pairs\"]},{\"session_number\":18,\"title\":\"Null Values and Handling Missing Data\",\"duration_mins\":60,\"objectives\":[\"Understand the impact of NULL in SQL operations and three-valued logic.\"],\"teaching_method\":\"Live SQL Coding Demonstrations\",\"activities\":[\"Querying datasets with null values\"],\"formative_assessment\":[\"Query output prediction check\"],\"engagement\":[\"Interactive polling\"]},{\"session_number\":19,\"title\":\"Nested Subqueries - Part 1\",\"duration_mins\":60,\"objectives\":[\"Formulate subqueries in WHERE clause using IN, NOT IN, EXISTS.\"],\"teaching_method\":\"Interactive Lab Sessions\",\"activities\":[\"Solving nested query exercises\"],\"formative_assessment\":[\"Lab assessment\"],\"engagement\":[\"Guided coding\"]},{\"session_number\":20,\"title\":\"Nested Subqueries - Part 2\",\"duration_mins\":60,\"objectives\":[\"Use scalar subqueries and correlated subqueries.\"],\"teaching_method\":\"Live SQL Coding Demonstrations\",\"activities\":[\"Writing correlated subqueries\"],\"formative_assessment\":[\"SQL Coding Assignment task 2\"],\"engagement\":[\"Code optimization challenge\"]},{\"session_number\":21,\"title\":\"Complex SQL Queries\",\"duration_mins\":60,\"objectives\":[\"Combine joins, subqueries, and grouping for advanced data retrieval.\"],\"teaching_method\":\"Interactive Lab Sessions\",\"activities\":[\"Enterprise reporting query design\"],\"formative_assessment\":[\"Peer review of queries\"],\"engagement\":[\"Hackathon style query writing\"]},{\"session_number\":22,\"title\":\"Views in SQL\",\"duration_mins\":60,\"objectives\":[\"Create, update, and drop virtual tables (views).\"],\"teaching_method\":\"Live SQL Coding Demonstrations\",\"activities\":[\"Implementing security and abstraction via views\"],\"formative_assessment\":[\"Lab evaluation\"],\"engagement\":[\"Hands-on practice\"]},{\"session_number\":23,\"title\":\"Joined Relations in SQL\",\"duration_mins\":60,\"objectives\":[\"Master Inner, Left Outer, Right Outer, and Full Outer Joins.\"],\"teaching_method\":\"Interactive Lab Sessions\",\"activities\":[\"Visualizing join outputs with sample data\"],\"formative_assessment\":[\"Join query quiz\"],\"engagement\":[\"Diagramming join sets\"]},{\"session_number\":24,\"title\":\"Advanced SQL Practice\",\"duration_mins\":60,\"objectives\":[\"Reinforce all SQL concepts learned so far.\"],\"teaching_method\":\"Live SQL Coding Demonstrations\",\"activities\":[\"Comprehensive lab problem set\"],\"formative_assessment\":[\"SQL Coding Assignment submission\"],\"engagement\":[\"Speed coding challenge\"]},{\"session_number\":25,\"title\":\"Unit 2 Review and Lab Test Preparation\",\"duration_mins\":60,\"objectives\":[\"Summarize relational algebra and SQL commands.\"],\"teaching_method\":\"Interactive Lab Sessions\",\"activities\":[\"Mock lab exam\"],\"formative_assessment\":[\"Internal Test 1 review component\"],\"engagement\":[\"Doubt clearing session\"]},{\"session_number\":26,\"title\":\"Unit 2 Assessment Review\",\"duration_mins\":60,\"objectives\":[\"Evaluate SQL coding solutions and common errors.\"],\"teaching_method\":\"Interactive Lab Sessions\",\"activities\":[\"Code walkthrough and optimization\"],\"formative_assessment\":[\"Internal Test 1 SQL evaluation\"],\"engagement\":[\"Code refactoring workshop\"]},{\"session_number\":27,\"title\":\"Features of Good Relational Design\",\"duration_mins\":60,\"objectives\":[\"Identify anomalies (insertion, deletion, update) in poorly designed schemas.\"],\"teaching_method\":\"Problem-Solving Sessions\",\"activities\":[\"Analyzing bad database designs\"],\"formative_assessment\":[\"Short quiz\"],\"engagement\":[\"Case study discussion\"]},{\"session_number\":28,\"title\":\"Atomic Domains and First Normal Form (1NF)\",\"duration_mins\":60,\"objectives\":[\"Understand atomicity of values and convert unnormalized tables to 1NF.\"],\"teaching_method\":\"Peer Teaching\",\"activities\":[\"Converting nested tables to flat relations\"],\"formative_assessment\":[\"Worksheet check\"],\"engagement\":[\"Peer explanation activity\"]},{\"session_number\":29,\"title\":\"Functional Dependency Theory\",\"duration_mins\":60,\"objectives\":[\"Define functional dependencies (FDs) and inference rules (Armstrong\'s axioms).\"],\"teaching_method\":\"Problem-Solving Sessions\",\"activities\":[\"Deriving FDs from business rules\"],\"formative_assessment\":[\"Assignment 2 release\"],\"engagement\":[\"Guided problem solving\"]},{\"session_number\":30,\"title\":\"Closure of a Set of Functional Dependencies\",\"duration_mins\":60,\"objectives\":[\"Compute the closure of a set of FDs ($F^+$).\"],\"teaching_method\":\"Problem-Solving Sessions\",\"activities\":[\"Computing FD closures on the board\"],\"formative_assessment\":[\"Board work check\"],\"engagement\":[\"Interactive derivation\"]},{\"session_number\":31,\"title\":\"Closure of Attribute Sets\",\"duration_mins\":60,\"objectives\":[\"Compute attribute closures ($X^+$) to test superkeys and candidate keys.\"],\"teaching_method\":\"Problem-Solving Sessions\",\"activities\":[\"Finding candidate keys using attribute closure algorithm\"],\"formative_assessment\":[\"Quiz 2\"],\"engagement\":[\"Step-by-step group calculation\"]},{\"session_number\":32,\"title\":\"Canonical Cover\",\"duration_mins\":60,\"objectives\":[\"Find the canonical cover ($Fc$) for a set of functional dependencies.\"],\"teaching_method\":\"Problem-Solving Sessions\",\"activities\":[\"Extraneous attribute elimination exercises\"],\"formative_assessment\":[\"Problem set check\"],\"engagement\":[\"Peer checking\"]},{\"session_number\":33,\"title\":\"Decomposition Using Functional Dependencies\",\"duration_mins\":60,\"objectives\":[\"Understand lossless-join and dependency-preserving decompositions.\"],\"teaching_method\":\"Peer Teaching\",\"activities\":[\"Testing decompositions for losslessness\"],\"formative_assessment\":[\"Formative test\"],\"engagement\":[\"Small group teaching\"]},{\"session_number\":34,\"title\":\"Third Normal Form (3NF)\",\"duration_mins\":60,\"objectives\":[\"Define 3NF and test schemas for 3NF compliance.\"],\"teaching_method\":\"Problem-Solving Sessions\",\"activities\":[\"Synthesizing 3NF relations\"],\"formative_assessment\":[\"Assignment 2 submission\"],\"engagement\":[\"Guided design exercise\"]},{\"session_number\":35,\"title\":\"Boyer-Codd Normal Form (BCNF)\",\"duration_mins\":60,\"objectives\":[\"Define BCNF and decompose schemas that violate BCNF.\"],\"teaching_method\":\"Problem-Solving Sessions\",\"activities\":[\"BCNF decomposition algorithm practice\"],\"formative_assessment\":[\"Internal Test 2 preparation quiz\"],\"engagement\":[\"Board race problem solving\"]},{\"session_number\":36,\"title\":\"Multi-valued Dependencies and Fourth Normal Form (4NF)\",\"duration_mins\":60,\"objectives\":[\"Identify multi-valued dependencies and apply 4NF.\"],\"teaching_method\":\"Peer Teaching\",\"activities\":[\"Analyzing multi-valued anomaly cases\"],\"formative_assessment\":[\"Concept check\"],\"engagement\":[\"Discussion panel\"]},{\"session_number\":37,\"title\":\"Normalization Practice Workshop\",\"duration_mins\":60,\"objectives\":[\"Practice end-to-end normalization from unnormalized forms to BCNF\\/4NF.\"],\"teaching_method\":\"Problem-Solving Sessions\",\"activities\":[\"Comprehensive case study normalization\"],\"formative_assessment\":[\"Internal Test 2\"],\"engagement\":[\"Collaborative problem solving\"]},{\"session_number\":38,\"title\":\"Unit 3 Review and Doubt Clearing\",\"duration_mins\":60,\"objectives\":[\"Review normalization and functional dependency algorithms.\"],\"teaching_method\":\"Peer Teaching\",\"activities\":[\"Student-led review of difficult topics\"],\"formative_assessment\":[\"Internal Test 2 review\"],\"engagement\":[\"Q&A session\"]},{\"session_number\":39,\"title\":\"Transaction Concept and Simple Transaction Model\",\"duration_mins\":60,\"objectives\":[\"Understand ACID properties of transactions.\"],\"teaching_method\":\"Lecture\",\"activities\":[\"Bank transfer transaction walkthrough\"],\"formative_assessment\":[\"Assignment 3 release\"],\"engagement\":[\"Real-world analogy discussion\"]},{\"session_number\":40,\"title\":\"Transaction Atomicity, Durability, and Storage Structure\",\"duration_mins\":60,\"objectives\":[\"Examine how atomicity and durability are maintained via storage management.\"],\"teaching_method\":\"Simulations\",\"activities\":[\"Transaction failure simulation\"],\"formative_assessment\":[\"Short quiz\"],\"engagement\":[\"Interactive simulation tool\"]},{\"session_number\":41,\"title\":\"Transaction Isolation and Serializability\",\"duration_mins\":60,\"objectives\":[\"Define conflict and view serializability.\"],\"teaching_method\":\"Lecture\",\"activities\":[\"Drawing precedence graphs to test serializability\"],\"formative_assessment\":[\"Worksheet check\"],\"engagement\":[\"Pair graph validation\"]},{\"session_number\":42,\"title\":\"Recoverable and Cascadeless Schedules\",\"duration_mins\":60,\"objectives\":[\"Distinguish between recoverable, cascadeless, and non-recoverable schedules.\"],\"teaching_method\":\"Case Study Analysis\",\"activities\":[\"Evaluating schedule logs\"],\"formative_assessment\":[\"Schedule analysis check\"],\"engagement\":[\"Group categorization activity\"]},{\"session_number\":43,\"title\":\"Concurrency Control and Lock-Based Protocols\",\"duration_mins\":60,\"objectives\":[\"Understand shared and exclusive locks.\",\"Apply Two-Phase Locking (2PL) protocol.\"],\"teaching_method\":\"Simulations\",\"activities\":[\"Lock compatibility matrix application\"],\"formative_assessment\":[\"Assignment 3 check\"],\"engagement\":[\"Interactive locking simulation\"]},{\"session_number\":44,\"title\":\"Timestamp-Based and Validation-Based Protocols\",\"duration_mins\":60,\"objectives\":[\"Implement timestamp ordering protocol.\",\"Understand validation-based concurrency control.\"],\"teaching_method\":\"Lecture\",\"activities\":[\"Timestamp conflict resolution exercises\"],\"formative_assessment\":[\"Pop quiz\"],\"engagement\":[\"Step-by-step walk-through\"]},{\"session_number\":45,\"title\":\"Deadlock Handling\",\"duration_mins\":60,\"objectives\":[\"Analyze deadlock prevention, detection, and recovery mechanisms.\"],\"teaching_method\":\"Case Study Analysis\",\"activities\":[\"Wait-for graph construction and cycle detection\"],\"formative_assessment\":[\"Deadlock quiz\"],\"engagement\":[\"Group scenario analysis\"]},{\"session_number\":46,\"title\":\"Transactions & Concurrency Control Problem Solving\",\"duration_mins\":60,\"objectives\":[\"Solve complex scheduling, locking, and deadlock problems.\"],\"teaching_method\":\"Simulations\",\"activities\":[\"Comprehensive transaction problem set\"],\"formative_assessment\":[\"Assignment 3 submission\"],\"engagement\":[\"Problem-solving competition\"]},{\"session_number\":47,\"title\":\"Unit 4 Review and Transaction Scenarios\",\"duration_mins\":60,\"objectives\":[\"Review all transaction management and concurrency control topics.\"],\"teaching_method\":\"Lecture\",\"activities\":[\"Review game \\/ structured Q&A\"],\"formative_assessment\":[\"End Semester Exam preparation check\"],\"engagement\":[\"Interactive trivia\"]},{\"session_number\":48,\"title\":\"Unit 4 Assessment Review\",\"duration_mins\":60,\"objectives\":[\"Review solutions for transaction management assessments.\"],\"teaching_method\":\"Case Study Analysis\",\"activities\":[\"Detailed paper review\"],\"formative_assessment\":[\"Internal test review\"],\"engagement\":[\"Open discussion\"]},{\"session_number\":49,\"title\":\"Failure Classification, Storage, and Recovery Atomicity\",\"duration_mins\":60,\"objectives\":[\"Classify database failures and understand stable storage principles.\"],\"teaching_method\":\"Flipped Classroom\",\"activities\":[\"Student presentations on types of database failures\"],\"formative_assessment\":[\"Quiz 3\"],\"engagement\":[\"Student-led presentation\"]},{\"session_number\":50,\"title\":\"Log-Based Recovery\",\"duration_mins\":60,\"objectives\":[\"Understand deferred-database modification and immediate-database modification recovery using logs.\"],\"teaching_method\":\"Technical Seminar\",\"activities\":[\"Tracing undo and redo operations from log files\"],\"formative_assessment\":[\"Log tracing worksheet\"],\"engagement\":[\"Step-by-step code\\/log tracing\"]},{\"session_number\":51,\"title\":\"Checkpoints and Shadow Paging\",\"duration_mins\":60,\"objectives\":[\"Implement checkpointing to reduce recovery overhead.\",\"Compare log-based recovery with shadow paging.\"],\"teaching_method\":\"Flipped Classroom\",\"activities\":[\"Comparing recovery overheads\"],\"formative_assessment\":[\"Short quiz\"],\"engagement\":[\"Comparative analysis debate\"]},{\"session_number\":52,\"title\":\"Recovery with Concurrent Transactions\",\"duration_mins\":60,\"objectives\":[\"Analyze advanced recovery techniques involving concurrent transaction execution.\"],\"teaching_method\":\"Technical Seminar\",\"activities\":[\"Advanced log analysis case study\"],\"formative_assessment\":[\"Seminar feedback rubric\"],\"engagement\":[\"Technical Q&A\"]},{\"session_number\":53,\"title\":\"Introduction to NoSQL Databases\",\"duration_mins\":60,\"objectives\":[\"Understand the shift from relational to NoSQL databases.\",\"Explore NoSQL data models (document, key-value, column, graph).\"],\"teaching_method\":\"Flipped Classroom\",\"activities\":[\"Exploring MongoDB\\/Redis basic concepts\"],\"formative_assessment\":[\"NoSQL concept check\"],\"engagement\":[\"Hands-on browser shell exploration\"]},{\"session_number\":54,\"title\":\"CAP Theorem\",\"duration_mins\":60,\"objectives\":[\"Analyze Consistency, Availability, and Partition Tolerance trade-offs in distributed systems.\"],\"teaching_method\":\"Technical Seminar\",\"activities\":[\"CAP theorem trade-off analysis for real systems\"],\"formative_assessment\":[\"Short written assessment\"],\"engagement\":[\"Case study debate\"]},{\"session_number\":55,\"title\":\"Introduction to Distributed Databases\",\"duration_mins\":60,\"objectives\":[\"Understand distributed database design, fragmentation, and replication.\"],\"teaching_method\":\"Flipped Classroom\",\"activities\":[\"Mapping distributed data storage architectures\"],\"formative_assessment\":[\"End Semester Exam preparation check\"],\"engagement\":[\"Group mapping activity\"]},{\"session_number\":56,\"title\":\"Advanced Databases and Recovery Review\",\"duration_mins\":60,\"objectives\":[\"Review log-based recovery, NoSQL, and distributed databases.\"],\"teaching_method\":\"Technical Seminar\",\"activities\":[\"Comprehensive review discussion\"],\"formative_assessment\":[\"End Semester Exam mock test component\"],\"engagement\":[\"Open floor review\"]},{\"session_number\":57,\"title\":\"Comprehensive Course Review - Part 1\",\"duration_mins\":60,\"objectives\":[\"Review Units 1 and 2 (ER Modeling, Relational Algebra, SQL).\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Rapid-fire problem solving across core modules\"],\"formative_assessment\":[\"Mock exam practice\"],\"engagement\":[\"Team quiz challenge\"]},{\"session_number\":58,\"title\":\"Comprehensive Course Review - Part 2\",\"duration_mins\":60,\"objectives\":[\"Review Unit 3 (Normalization and Functional Dependencies).\"],\"teaching_method\":\"Problem-Solving Sessions\",\"activities\":[\"Solving complex normalization and closure problems\"],\"formative_assessment\":[\"Practice problem review\"],\"engagement\":[\"Board work review\"]},{\"session_number\":59,\"title\":\"Comprehensive Course Review - Part 3\",\"duration_mins\":60,\"objectives\":[\"Review Units 4 and 5 (Transactions, Concurrency, Recovery, NoSQL).\"],\"teaching_method\":\"Lecture\",\"activities\":[\"Final doubt clearing and key formula\\/algorithm recap\"],\"formative_assessment\":[\"End Semester Exam final prep check\"],\"engagement\":[\"Comprehensive Q&A\"]},{\"session_number\":60,\"title\":\"Final Course Wrap-Up and Exam Strategy\",\"duration_mins\":60,\"objectives\":[\"Discuss final exam structure, expectations, and answer presentation strategies.\"],\"teaching_method\":\"Lecture\",\"activities\":[\"Sample question paper discussion and time management tips\"],\"formative_assessment\":[\"End Semester Exam\"],\"engagement\":[\"Motivational closing discussion\"]}]}','gemini-3.5-flash-lite',NULL,NULL,20419,'success',NULL,'course_plan',1,'2026-11-11 11:59:34'),(4,1,3,'ppt','ppt','{\"title\":\"DBMS\",\"subject\":\"Database Management Systems\",\"unit\":1,\"provider\":\"gemini\"}','{\"slides\":[{\"number\":1,\"title\":\"Database Management Systems (DBMS)\",\"layout\":\"content\",\"bullets\":[\"Institution: K.L.N College of Engineering\",\"Department: Computer Science and Engineering\",\"Course: Database Management Systems\",\"Comprehensive Full Course Coverage (Units 1 to 5)\"],\"speaker_notes\":\"Welcome to the comprehensive course on Database Management Systems. Today we cover the entire curriculum from foundational data models to transaction processing and NoSQL databases.\",\"unit_tag\":\"Overview\"},{\"number\":2,\"title\":\"Course Learning Objectives\",\"layout\":\"content\",\"bullets\":[\"Design Entity-Relationship models and map them to normalized relational schemas.\",\"Formulate complex relational algebra expressions and SQL queries for data retrieval.\",\"Analyze functional dependencies to achieve optimal database normalization up to BCNF and 4NF.\",\"Evaluate transaction schedules using serializability and concurrency control protocols.\",\"Implement recovery mechanisms and distinguish relational databases from NoSQL architectures.\"],\"speaker_notes\":\"Review these core objectives carefully. They guide our progression from conceptual design all the way to physical recovery and modern distributed systems.\",\"unit_tag\":\"Overview\"},{\"number\":3,\"title\":\"Unit 1: Data Models, Architecture & ER Design\",\"layout\":\"content\",\"bullets\":[\"Data Independence: Separation of ANSI-SPARC 3-schema architecture (Internal, Conceptual, External) isolating applications from physical storage changes.\",\"Database Languages: DDL (Data Definition Language) for schema definition, DML (Data Manipulation Language) for queries and updates.\",\"ER Modeling: Entities, attributes, mapping cardinalities (1:1, 1:N, N:M), and primary\\/foreign keys.\",\"Schema Reduction: Systematic transformation of ER diagrams into relational tables preserving referential integrity.\"],\"speaker_notes\":\"Unit 1 establishes how real-world domains are modeled conceptually and translated into structured schemas while maintaining data independence.\",\"unit_tag\":\"Unit 1\"},{\"number\":4,\"title\":\"Unit 2: Relational Algebra & Advanced SQL\",\"layout\":\"content\",\"bullets\":[\"Fundamental Operations: Selection (sigma), Projection (pi), Union, Set Difference, Cartesian Product, and Rename.\",\"Extended Operations: Outer joins, left\\/right\\/full joins, and aggregate functions (SUM, AVG, COUNT).\",\"SQL Subqueries & Views: Nested subqueries for complex filtering, correlated subqueries, and virtual tables (Views) for security and abstraction.\",\"Null Logic: Three-valued logic handling of unknown or missing data values during evaluations.\"],\"speaker_notes\":\"Unit 2 bridges theory and practice. Relational algebra provides the formal foundation, while SQL executes these operations on real database instances.\",\"unit_tag\":\"Unit 2\"},{\"number\":5,\"title\":\"Unit 3: Functional Dependencies & Normalization\",\"layout\":\"content\",\"bullets\":[\"Functional Dependencies (FD): Constraints where attribute set X uniquely determines attribute set Y (X -> Y).\",\"Axioms & Closure: Armstrong\'s axioms, computing attribute closures (X+), and canonical covers to minimize redundant FDs.\",\"Normal Forms: 1NF (atomic domains), 2NF (full functional dependency), and 3NF (eliminating transitive dependencies).\",\"Advanced Normal Forms: BCNF (every determinant is a candidate key) and 4NF (eliminating multi-valued dependencies).\"],\"speaker_notes\":\"Normalization eliminates redundancy and insertion, update, and deletion anomalies. We use attribute closures and canonical covers to mathematically verify normal forms.\",\"unit_tag\":\"Unit 3\"},{\"number\":6,\"title\":\"Unit 4: Transactions & Concurrency Control\",\"layout\":\"content\",\"bullets\":[\"ACID Properties: Atomicity, Consistency, Isolation, and Durability ensuring reliable execution of units of work.\",\"Serializability: Conflict and view serializability ensuring concurrent execution yields identical results to serial execution.\",\"Lock-Based Protocols: Two-Phase Locking (2PL) and strict\\/rigorous 2PL guaranteeing conflict serializability.\",\"Deadlock Management: Deadlock prevention schemes (wait-die, wound-wait) and detection via wait-for graphs.\"],\"speaker_notes\":\"Transactions must maintain database consistency despite concurrent access and system failures. Isolation levels and locking protocols manage this concurrency.\",\"unit_tag\":\"Unit 4\"},{\"number\":7,\"title\":\"Unit 5: Crash Recovery & NoSQL Databases\",\"layout\":\"content\",\"bullets\":[\"Log-Based Recovery: Write-Ahead Logging (WAL), undo\\/redo operations, and checkpointing for crash recovery.\",\"Alternative Recovery: Shadow paging maintaining two page tables during transaction execution.\",\"CAP Theorem: Distributed systems must choose at most two among Consistency, Availability, and Partition Tolerance.\",\"NoSQL Architecture: Introduction to key-value, document, and columnar stores for horizontal scalability.\"],\"speaker_notes\":\"Unit 5 addresses what happens when systems fail and how modern distributed architectures scale beyond traditional relational limits using the CAP theorem.\",\"unit_tag\":\"Unit 5\"},{\"number\":8,\"title\":\"Unit Summary & Review Questions\",\"layout\":\"summary\",\"bullets\":[\"Summary: Covered full database lifecycle from ER modeling and SQL querying to normalization, concurrency control, and recovery.\",\"Review Question 1: Given a relation R(A,B,C,D) with FDs {A->B, B->C}, decompose into 3NF and BCNF.\",\"Review Question 2: Explain how Two-Phase Locking guarantees conflict serializability.\",\"Review Question 3: Discuss the implications of the CAP theorem when designing a distributed e-commerce database.\"],\"speaker_notes\":\"Review these questions to test your grasp of the core concepts across all five units. Be prepared to solve similar problems in examinations.\",\"unit_tag\":\"Overview\"},{\"number\":9,\"title\":\"Thank You\",\"layout\":\"close\",\"bullets\":[\"Department of Computer Science and Engineering\",\"K.L.N College of Engineering\",\"Open for Questions and Discussion\"],\"speaker_notes\":\"Thank you for your attention. We will now open the floor for any questions regarding the DBMS curriculum.\",\"unit_tag\":\"Overview\"}]}','gemini-3.5-flash-lite',NULL,NULL,17565,'success',NULL,'presentation',1,'2026-11-11 12:00:36'),(5,1,3,'assignment','assignment','{\"type\":\"essay\",\"subject\":\"Database Management Systems\",\"class_id\":1,\"provider\":\"gemini\"}','{\"title\":\"Advanced Database Management Systems Essay Assignment\",\"description\":\"A comprehensive essay assignment focusing on two major conceptual and architectural paradigms in Database Management Systems: Transaction Processing & Concurrency Control, and Distributed Databases & NoSQL Systems.\",\"instructions\":[\"Write a well-structured essay addressing both major questions provided.\",\"Ensure each section includes clear theoretical explanations, real-world examples, and comparative analysis.\",\"The essay must be between 1500 to 2000 words.\",\"Properly cite academic sources and textbooks used for the arguments.\",\"Submit the assignment in PDF format by the stipulated deadline.\"],\"max_marks\":50,\"rubric\":[{\"criterion\":\"Concurrency Control and ACID Properties\",\"description\":\"Explanation of transaction management, ACID properties, and how concurrency control protocols (like 2PL and Timestamp Ordering) prevent anomalies.\",\"marks\":15,\"clo\":\"CLO2\",\"bloom\":\"K3\",\"levels\":[\"Poor (0-5 marks): Inaccurate or incomplete explanation of transactions.\",\"Average (6-10 marks): Basic understanding of ACID and locking without deep analysis.\",\"Excellent (11-15 marks): Comprehensive and accurate application of concurrency control mechanisms.\"]},{\"criterion\":\"Distributed Databases and CAP Theorem\",\"description\":\"Analysis of distributed database architectures, data fragmentation, replication strategies, and trade-offs defined by the CAP theorem.\",\"marks\":15,\"clo\":\"CLO4\",\"bloom\":\"K3\",\"levels\":[\"Poor (0-5 marks): Lacks clarity on distributed systems and CAP theorem.\",\"Average (6-10 marks): Mentions CAP theorem and distribution with limited depth.\",\"Excellent (11-15 marks): Deep critical analysis of distributed data management and CAP trade-offs.\"]},{\"criterion\":\"Critical Analysis and Comparison\",\"description\":\"Ability to compare relational DBMS scalability challenges with NoSQL\\/Distributed solutions using concrete scenarios.\",\"marks\":10,\"clo\":\"CLO3\",\"bloom\":\"K4\",\"levels\":[\"Poor (0-3 marks): No meaningful comparison provided.\",\"Average (4-7 marks): Surface-level comparison of SQL vs NoSQL.\",\"Excellent (8-10 marks): Insightful comparative evaluation based on architectural needs.\"]},{\"criterion\":\"Structure, Clarity, and Citations\",\"description\":\"Overall organization, academic tone, logical flow of arguments, and proper referencing.\",\"marks\":10,\"clo\":\"CLO1\",\"bloom\":\"K2\",\"levels\":[\"Poor (0-3 marks): Poor grammar, disorganized structure, missing citations.\",\"Average (4-7 marks): Adequate structure and readability with minor flaws.\",\"Excellent (8-10 marks): Flawless academic writing, clear structure, and robust citations.\"]}]}','gemini-3.5-flash-lite',NULL,NULL,5269,'success',NULL,'assignment',1,'2026-11-11 12:01:12'),(6,1,3,'questions','questions','{\"type\":\"short\",\"unit\":1,\"klevel\":\"K2\",\"count\":5,\"subject\":\"Database Management Systems\",\"provider\":\"gemini\"}','{\"questions\":[{\"stem\":\"Explain the concept of physical data independence in a database management system, and provide a brief illustrative example of how it protects application programs.\",\"correct_answer\":\"Physical data independence is the capacity to modify the internal schema (e.g., changing file organizations, indexing strategies, or storage structures) without having to alter the conceptual schema or existing application programs. For example, if a DBA decides to switch the underlying storage of a large employee table from an unindexed sequential file to a B+-tree indexed file, the application queries that retrieve employee records remain completely unaffected because the logical view provided by the conceptual schema does not change.\",\"explanation\":\"K2 level requires explaining a concept in one\'s own words and providing an example. This question targets physical data independence, explaining both the mechanism and its practical protective effect on applications.\",\"marks\":5,\"difficulty\":\"medium\",\"bloom_k_level\":\"K2\",\"unit_number\":1},{\"stem\":\"Contrast the roles of the conceptual schema and the physical schema in the three-schema database architecture, using a practical database scenario to clarify their differences.\",\"correct_answer\":\"The conceptual schema describes the overall database structure for all users, hiding the details of physical storage structures and focusing on entities, data types, relationships, and constraints. In contrast, the physical schema describes how the data is actually stored on secondary storage devices, including details regarding file structures, record placements, and compression or indexing techniques. For example, in a university database, the conceptual schema defines the \'Student\' entity with attributes like ID, Name, and GPA, whereas the physical schema specifies that the Student relation is stored as a clustered index on the student_id field within a specific disk block allocation.\",\"explanation\":\"Tests the understanding of schema layers in database architecture by asking for a comparison and a concrete scenario.\",\"marks\":5,\"difficulty\":\"medium\",\"bloom_k_level\":\"K2\",\"unit_number\":1},{\"stem\":\"Explain the significance of mapping cardinalities in an Entity-Relationship (ER) model, and describe how a one-to-many relationship is typically translated during the reduction to a relational schema.\",\"correct_answer\":\"Mapping cardinalities express the maximum number of relationship instances that an entity can participate in, categorizing relationships as one-to-one, one-to-many, or many-to-many. During the reduction of a binary one-to-many relationship set from an ER diagram to a relational schema, the entity on the \'many\' side of the relationship is augmented with a foreign key that references the primary key of the entity on the \'one\' side. For example, in a Department-to-Employee one-to-many relationship, the Employee relation receives \'dept_id\' as a foreign key pointing to the Department relation.\",\"explanation\":\"Evaluates comprehension of ER modeling constraints and the algorithmic translation (reduction) process into relational schemas.\",\"marks\":5,\"difficulty\":\"medium\",\"bloom_k_level\":\"K2\",\"unit_number\":1},{\"stem\":\"Discuss the primary purpose of database languages, specifically differentiating between Data Definition Language (DDL) and Data Manipulation Language (DML) with functional examples.\",\"correct_answer\":\"Database languages are specialized languages used by database administrators and users to specify database schemas, express queries, and update data. DDL is used to define and modify the database structure and constraints, such as creating tables or altering columns (e.g., \'CREATE TABLE Instructor (ID INT PRIMARY KEY, name VARCHAR(50));\'). DML, on the other hand, enables users to access or manipulate data organized by the appropriate data model, handling operations such as retrieval, insertion, deletion, and modification of actual records (e.g., \'INSERT INTO Instructor VALUES (101, \\\\\'Alice\\\\\');\').\",\"explanation\":\"Assesses the understanding of database system languages and the distinct functions of DDL versus DML.\",\"marks\":5,\"difficulty\":\"medium\",\"bloom_k_level\":\"K2\",\"unit_number\":1},{\"stem\":\"Explain why weak entity sets require a supervising strong entity set, and describe how this dependency is represented in an ER diagram and resolved in a relational schema.\",\"correct_answer\":\"A weak entity set is one that does not possess sufficient attributes to form a primary key of its own; thus, its existence depends on a strong entity set (referred to as the identifying owner). In an ER diagram, a weak entity is depicted with a double-lined rectangle, and its identifying relationship is shown with a double-lined diamond. When reducing this to a relational schema, the weak entity\'s relation includes its own partial discriminator attributes along with the primary key attributes of the strong entity set as a foreign key, with the combined set forming the primary key of the weak entity\'s relation.\",\"explanation\":\"Checks comprehension of weak entities, their notation in ER diagrams, and their structural conversion into relational tables.\",\"marks\":5,\"difficulty\":\"hard\",\"bloom_k_level\":\"K2\",\"unit_number\":1}]}','gemini-3.5-flash-lite',NULL,NULL,5816,'success',NULL,'question_bank',1,'2026-11-11 12:03:12'),(7,1,3,'course_plan','course_plan','{\"subject\":\"Computer Networks\",\"credits\":\"4\",\"university\":\"Autonomous\",\"template\":\"standard\",\"provider\":\"gemini\"}','{\"title\":\"Computer Networks\",\"learning_outcomes\":[\"Understand the fundamental concepts of computer networks and the OSI\\/TCP-IP reference models.\",\"Analyze data link layer protocols, error detection\\/correction, and medium access control mechanisms.\",\"Design and implement routing algorithms and IP addressing schemes at the network layer.\",\"Evaluate transport layer protocols for reliable end-to-end communication and congestion control.\",\"Analyze application layer protocols and understand the basics of network security.\"],\"units\":[{\"unit_number\":1,\"title\":\"Introduction and Physical Layer\",\"hours\":12,\"topics\":[\"Uses of Computer Networks\",\"Network Hardware and Software\",\"Reference Models (OSI and TCP\\/IP)\",\"Example Networks\",\"Guided and Unguided Transmission Media\"],\"outcomes\":[\"Compare OSI and TCP\\/IP reference models.\",\"Identify different types of transmission media and network hardware.\"],\"bloom_k_level\":\"K2\",\"teaching_methods\":[\"Chalk and Talk\",\"PPT Presentation\",\"Video Demonstration\"],\"assessment\":[\"Quiz\",\"Assignment 1\",\"Internal Test 1\"]},{\"unit_number\":2,\"title\":\"Data Link Layer\",\"hours\":12,\"topics\":[\"Data Link Layer Design Issues\",\"Error Detection and Correction\",\"Elementary Data Link Protocols\",\"Sliding Window Protocols\",\"Multiple Access Protocols\",\"Ethernet\"],\"outcomes\":[\"Apply error detection and correction codes.\",\"Analyze sliding window and multiple access protocols.\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"Problem-solving sessions\",\"Interactive Lecture\",\"Simulation using Packet Tracer\"],\"assessment\":[\"Numerical Assignments\",\"Internal Test 1\",\"Lab Evaluation\"]},{\"unit_number\":3,\"title\":\"Network Layer\",\"hours\":12,\"topics\":[\"Network Layer Design Issues\",\"Routing Algorithms (Distance Vector, Link State)\",\"Congestion Control Algorithms\",\"Quality of Service\",\"Internetworking\",\"IPv4 and IPv6 Addressing\"],\"outcomes\":[\"Implement routing and congestion control algorithms.\",\"Calculate subnet masks and configure IPv4\\/IPv6 addresses.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Chalk and Talk\",\"Case Study\",\"Hands-on IP Subnetting\"],\"assessment\":[\"Internal Test 2\",\"Quiz\",\"Subnetting Assignment\"]},{\"unit_number\":4,\"title\":\"Transport Layer\",\"hours\":12,\"topics\":[\"The Transport Service\",\"Elements of Transport Protocols\",\"Congestion Control\",\"UDP (User Datagram Protocol)\",\"TCP (Transmission Control Protocol)\"],\"outcomes\":[\"Compare connectionless and connection-oriented transport protocols.\",\"Analyze TCP congestion control mechanisms.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Interactive Lecture\",\"Wireshark Protocol Analysis\"],\"assessment\":[\"Internal Test 2\",\"Wireshark Lab Report\"]},{\"unit_number\":5,\"title\":\"Application Layer and Network Security\",\"hours\":12,\"topics\":[\"DNS (Domain Name System)\",\"Electronic Mail (SMTP, IMAP)\",\"World Wide Web (HTTP)\",\"Cryptography Basics\",\"Digital Signatures and Firewalls\"],\"outcomes\":[\"Explain the working of core application layer protocols.\",\"Understand basic cryptographic principles and network security mechanisms.\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"PPT Presentation\",\"Demonstration of DNS lookup and HTTP traffic\"],\"assessment\":[\"End Semester Exam\",\"Assignment 3\",\"Quiz\"]}],\"weekly_plan\":[{\"week\":1,\"topics\":\"Uses of Computer Networks, Network Hardware and Software\"},{\"week\":2,\"topics\":\"Reference Models (OSI and TCP\\/IP), Example Networks\"},{\"week\":3,\"topics\":\"Guided and Unguided Transmission Media\"},{\"week\":4,\"topics\":\"Data Link Layer Design Issues, Error Detection and Correction\"},{\"week\":5,\"topics\":\"Elementary Data Link Protocols, Sliding Window Protocols\"},{\"week\":6,\"topics\":\"Multiple Access Protocols, Ethernet\"},{\"week\":7,\"topics\":\"Network Layer Design Issues, Routing Algorithms\"},{\"week\":8,\"topics\":\"Congestion Control Algorithms, Quality of Service\"},{\"week\":9,\"topics\":\"Internetworking, IPv4 and IPv6 Addressing\"},{\"week\":10,\"topics\":\"The Transport Service, Elements of Transport Protocols\"},{\"week\":11,\"topics\":\"UDP and TCP, Congestion Control in Transport Layer\"},{\"week\":12,\"topics\":\"DNS, Electronic Mail (SMTP, IMAP)\"},{\"week\":13,\"topics\":\"World Wide Web (HTTP)\"},{\"week\":14,\"topics\":\"Cryptography Basics, Digital Signatures\"},{\"week\":15,\"topics\":\"Firewalls and Network Security Overview, Revision\"}],\"resources\":[\"Andrew S. Tanenbaum and David J. Wetherall, \'Computer Networks\', 5th Edition, Pearson, 2010.\",\"Behrouz A. Forouzan, \'Data Communications and Networking\', 4th Edition, McGraw-Hill, 2007.\",\"J. Kurose and K. Ross, \'Computer Networking: A Top-Down Approach\', 6th Edition, Pearson, 2012.\"],\"expert_advice\":[\"Emphasize hands-on packet analysis using Wireshark to bridge theory and practice.\",\"Conduct regular problem-solving sessions for IP subnetting and routing algorithms.\",\"Align continuous internal assessments with Bloom\'s higher cognitive levels (K3 and K4).\"],\"bloom_distribution\":{\"K1\":15,\"K2\":25,\"K3\":30,\"K4\":20,\"K5\":5,\"K6\":5},\"ai_score\":9.5}','gemini-3.5-flash-lite',NULL,NULL,4735,'success',NULL,NULL,NULL,'2026-11-12 03:32:11'),(8,1,3,'lesson','lesson','{\"plan_id\":2,\"provider\":\"gemini\"}','{\"text\":\"[\\n  {\\n    \\\"session_number\\\": 1,\\n    \\\"title\\\": \\\"Uses of Computer Networks - Overview\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n      \\\"Understand the primary applications of computer networks in business and home environments.\\\"\\n    ],\\n    \\\"teaching_method\\\": \\\"Chalk and Talk\\\",\\n    \\\"activities\\\": [\\n      \\\"Brainstorming real-world network usage examples.\\\"\\n    ],\\n    \\\"formative_assessment\\\": [\\n      \\\"Short oral Q&A\\\"\\n    ],\\n    \\\"engagement\\\": [\\n      \\\"Think-Pair-Share\\\"\\n    ]\\n  },\\n  {\\n    \\\"session_number\\\": 2,\\n    \\\"title\\\": \\\"Uses of Computer Networks - Mobile and Social Issues\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n      \\\"Analyze mobile networks and social, ethical, and legal issues.\\\"\\n    ],\\n    \\\"teaching_method\\\": \\\"PPT Presentation\\\",\\n    \\\"activities\\\": [\\n      \\\"Discussion on privacy and security in modern networks.\\\"\\n    ],\\n    \\\"formative_assessment\\\": [\\n      \\\"Quiz\\\"\\n    ],\\n    \\\"engagement\\\": [\\n      \\\"Class debate\\\"\\n    ]\\n  },\\n  {\\n    \\\"session_number\\\": 3,\\n    \\\"title\\\": \\\"Network Hardware - LAN, MAN, WAN\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n      \\\"Identify different network hardware components and geographic scopes.\\\"\\n    ],\\n    \\\"teaching_method\\\": \\\"Chalk and Talk\\\",\\n    \\\"activities\\\": [\\n      \\\"Drawing network topologies on the board.\\\"\\n    ],\\n    \\\"formative_assessment\\\": [\\n      \\\"Concept check questions\\\"\\n    ],\\n    \\\"engagement\\\": [\\n      \\\"Interactive diagramming\\\"\\n    ]\\n  },\\n  {\\n    \\\"session_number\\\": 4,\\n    \\\"title\\\": \\\"Network Software - Protocol Hierarchies\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n      \\\"Understand protocol stacks, design issues for the layers, and service primitives.\\\"\\n    ],\\n    \\\"teaching_method\\\": \\\"PPT Presentation\\\",\\n    \\\"activities\\\": [\\n      \\\"Mapping layered architectures to real-world postal analogies.\\\"\\n    ],\\n    \\\"formative_assessment\\\": [\\n      \\\"Assignment 1 part A\\\"\\n    ],\\n    \\\"engagement\\\": [\\n      \\\"Analogy mapping\\\"\\n    ]\\n  },\\n  {\\n    \\\"session_number\\\": 5,\\n    \\\"title\\\": \\\"Reference Models - OSI Model\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n      \\\"Examine the 7 layers of the OSI reference model in detail.\\\"\\n    ],\\n    \\\"teaching_method\\\": \\\"Chalk and Talk\\\",\\n    \\\"activities\\\": [\\n      \\\"Detailed walk-through of each layer\'s functions.\\\"\\n    ],\\n    \\\"formative_assessment\\\": [\\n      \\\"Quiz on layer functions\\\"\\n    ],\\n    \\\"engagement\\\": [\\n      \\\"Mnemonic creation challenge\\\"\\n    ]\\n  },\\n  {\\n    \\\"session_number\\\": 6,\\n    \\\"title\\\": \\\"Reference Models - TCP\\/IP Model\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n      \\\"Examine the TCP\\/IP reference model and compare it with OSI.\\\"\\n    ],\\n    \\\"teaching_method\\\": \\\"PPT Presentation\\\",\\n    \\\"activities\\\": [\\n      \\\"Comparative matrix creation in groups.\\\"\\n    ],\\n    \\\"formative_assessment\\\": [\\n      \\\"Comparison worksheet\\\"\\n    ],\\n    \\\"engagement\\\": [\\n      \\\"Group comparison matrix\\\"\\n    ]\\n  },\\n  {\\n    \\\"session_number\\\": 7,\\n    \\\"title\\\": \\\"Example Networks - Internet, ARPANET, WLANs\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n      \\\"Explore historical and modern example networks like ARPANET and modern WLANs.\\\"\\n    ],\\n    \\\"teaching_method\\\": \\\"Video Demonstration\\\",\\n    \\\"activities\\\": [\\n      \\\"Watching documentary clips on ARPANET history and evolution.\\\"\\n    ],\\n    \\\"formative_assessment\\\": [\\n      \\\"Reflection note\\\"\\n    ],\\n    \\\"engagement\\\": [\\n      \\\"Video analysis\\\"\\n    ]\\n  },\\n  {\\n    \\\"session_number\\\": 8,\\n    \\\"title\\\": \\\"Guided Transmission Media - Twisted Pair and Coaxial Cable\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n      \\\"Identify characteristics and use cases of twisted pair and coaxial cables.\\\"\\n    ],\\n    \\\"teaching_method\\\": \\\"Chalk and Talk\\\",\\n    \\\"activities\\\": [\\n      \\\"Physical inspection of cable samples if available.\\\"\\n    ],\\n    \\\"formative_assessment\\\": [\\n      \\\"Quick quiz\\\"\\n    ],\\n    \\\"engagement\\\": [\\n      \\\"Hands-on cable inspection\\\"\\n    ]\\n  },\\n  {\\n    \\\"session_number\\\": 9,\\n    \\\"title\\\": \\\"Guided Transmission Media - Fiber Optics\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n      \\\"Understand the principles of fiber optics and light propagation.\\\"\\n    ],\\n    \\\"teaching_method\\\": \\\"PPT Presentation\\\",\\n    \\\"activities\\\": [\\n      \\\"Calculating attenuation and bandwidth metrics.\\\"\\n    ],\\n    \\\"formative_assessment\\\": [\\n      \\\"Numerical check\\\"\\n    ],\\n    \\\"engagement\\\": [\\n      \\\"Problem-solving sprint\\\"\\n    ]\\n  },\\n  {\\n    \\\"session_number\\\": 10,\\n    \\\"title\\\": \\\"Unguided Transmission Media - Wireless Propagation\\\",\\n    \\\"duration_mins\\\": 60,\\n    \\\"objectives\\\": [\\n   