INSERT INTO `assignments` VALUES (1,1,NULL,3,1,1,'Advanced Database Management Systems Essay Assignment','essay','A comprehensive essay assignment focusing on two major conceptual and architectural paradigms in Database Management Systems: Transaction Processing & Concurrency Control, and Distributed Databases & NoSQL Systems.','[{\"criterion\":\"Concurrency Control and ACID Properties\",\"description\":\"Explanation of transaction management, ACID properties, and how concurrency control protocols (like 2PL and Timestamp Ordering) prevent anomalies.\",\"marks\":15,\"clo\":\"CLO2\",\"bloom\":\"K3\",\"levels\":\"Poor (0-5 marks): Inaccurate or incomplete explanation of transactions.; Average (6-10 marks): Basic understanding of ACID and locking without deep analysis.; Excellent (11-15 marks): Comprehensive and accurate application of concurrency control mechanisms.\",\"weight\":null},{\"criterion\":\"Distributed Databases and CAP Theorem\",\"description\":\"Analysis of distributed database architectures, data fragmentation, replication strategies, and trade-offs defined by the CAP theorem.\",\"marks\":15,\"clo\":\"CLO4\",\"bloom\":\"K3\",\"levels\":\"Poor (0-5 marks): Lacks clarity on distributed systems and CAP theorem.; Average (6-10 marks): Mentions CAP theorem and distribution with limited depth.; Excellent (11-15 marks): Deep critical analysis of distributed data management and CAP trade-offs.\",\"weight\":null},{\"criterion\":\"Critical Analysis and Comparison\",\"description\":\"Ability to compare relational DBMS scalability challenges with NoSQL\\/Distributed solutions using concrete scenarios.\",\"marks\":10,\"clo\":\"CLO3\",\"bloom\":\"K4\",\"levels\":\"Poor (0-3 marks): No meaningful comparison provided.; Average (4-7 marks): Surface-level comparison of SQL vs NoSQL.; Excellent (8-10 marks): Insightful comparative evaluation based on architectural needs.\",\"weight\":null},{\"criterion\":\"Structure, Clarity, and Citations\",\"description\":\"Overall organization, academic tone, logical flow of arguments, and proper referencing.\",\"marks\":10,\"clo\":\"CLO1\",\"bloom\":\"K2\",\"levels\":\"Poor (0-3 marks): Poor grammar, disorganized structure, missing citations.; Average (4-7 marks): Adequate structure and readability with minor flaws.; Excellent (8-10 marks): Flawless academic writing, clear structure, and robust citations.\",\"weight\":null}]',50.00,'2026-12-05 04:00:00','[\"Write a well-structured essay addressing both major questions provided.\",\"Ensure each section includes clear theoretical explanations, real-world examples, and comparative analysis.\",\"The essay must be between 1500 to 2000 words.\",\"Properly cite academic sources and textbooks used for the arguments.\",\"Submit the assignment in PDF format by the stipulated deadline.\"]',1,'published','{\"bulk_group\":null,\"from_template_id\":null,\"context\":\"generate the top 2 big question of DBMS\"}','2026-11-11 12:01:12','2026-11-11 12:01:12'),(2,1,NULL,3,2,1,'Case Study: Enterprise Network Redesign and Troubleshooting','case_study','Global Logistics Corp. is experiencing severe network latency, packet loss, and security vulnerabilities across its headquarters and three regional branches. The current flat network topology causes broadcast storms, and the lack of subnetting leads to IP exhaustion. As the Lead Network Architect, you are required to analyze the existing network bottlenecks, propose an optimized hierarchical IP addressing and routing scheme, implement secure VLAN configurations, and diagnose specific routing protocol failures.','[{\"criterion\":\"Network Problem Analysis\",\"description\":\"Accurately identify the root causes of latency, broadcast storms, and IP exhaustion from the given scenario.\",\"marks\":10,\"clo\":\"CLO1\",\"bloom\":\"K2\",\"levels\":\"Poor: Fails to identify core issues; Average: Identifies some issues with minor gaps; Excellent: Thoroughly analyzes and categorizes all network bottlenecks\",\"weight\":null},{\"criterion\":\"IP Addressing and VLSM Design\",\"description\":\"Design an optimal hierarchical IP addressing scheme using Variable Length Subnet Masking (VLSM).\",\"marks\":10,\"clo\":\"CLO2\",\"bloom\":\"K3\",\"levels\":\"Poor: Major calculation errors or inefficient IP usage; Average: Mostly correct subnetting with minor inefficiencies; Excellent: Flawless VLSM design meeting all constraints and future scalability\",\"weight\":null},{\"criterion\":\"VLAN and Inter-VLAN Routing Implementation\",\"description\":\"Configure VLANs, trunking, and router-on-a-stick or multilayer switching for traffic segmentation.\",\"marks\":10,\"clo\":\"CLO3\",\"bloom\":\"K3\",\"levels\":\"Poor: Incorrect VLAN assignments or routing configuration; Average: Functional configuration with missing security best practices; Excellent: Robust and secure VLAN implementation with proper inter-VLAN routing\",\"weight\":null},{\"criterion\":\"Routing Protocol Troubleshooting\",\"description\":\"Diagnose OSPF routing loops, convergence delays, and propose corrective configurations.\",\"marks\":10,\"clo\":\"CLO4\",\"bloom\":\"K3\",\"levels\":\"Poor: Unable to locate the routing failure; Average: Identifies the issue but provides an incomplete fix; Excellent: Accurately pinpoints the routing anomaly and provides an optimal solution\",\"weight\":null},{\"criterion\":\"Security and Comprehensive Reporting\",\"description\":\"Integrate security policies (ACLs) and present the final architectural report clearly and professionally.\",\"marks\":10,\"clo\":\"CLO5\",\"bloom\":\"K3\",\"levels\":\"Poor: Lacks security considerations and poor report structure; Average: Basic security measures included with adequate presentation; Excellent: Comprehensive security integration with clear diagrams and professional documentation\",\"weight\":null}]',50.00,'2026-11-13 04:00:00','[\"Analyze the provided network topology and traffic bottleneck logs for Global Logistics Corp.\",\"Propose a redesigned hierarchical IP addressing scheme using VLSM to optimize subnet allocation.\",\"Configure VLANs and inter-VLAN routing to segment traffic and mitigate broadcast storms.\",\"Identify and troubleshoot the OSPF routing loop and convergence issues present in the branch offices.\",\"Submit a comprehensive report including network diagrams, IP allocation tables, configuration snippets, and justification for the security measures implemented.\"]',1,'published','{\"bulk_group\":null,\"from_template_id\":null,\"context\":\"genearte the cast study question for CN\"}','2026-11-12 03:34:38','2026-11-12 03:34:38');
