INSERT INTO `course_plan_versions` VALUES (1,1,1,'{\"title\":\"Database Management Systems\",\"learning_outcomes\":[\"Understand the fundamental concepts of Database Management Systems and data models.\",\"Design entity-relationship diagrams and map them to relational database schemas.\",\"Formulate complex SQL queries using DDL, DML, DCL, and TCL commands.\",\"Apply normalization techniques to reduce data redundancy and maintain integrity.\",\"Analyze transaction management, concurrency control protocols, and recovery techniques.\"],\"units\":[{\"unit_number\":1,\"title\":\"Introduction to DBMS and ER Model\",\"hours\":12,\"topics\":[\"Database System Applications\",\"Purpose of Database Systems\",\"View of Data\",\"Data Independence\",\"Database Languages\",\"Data Models\",\"Database Architecture\",\"Entity-Relationship (ER) Model\",\"Mapping Cardinalities\",\"Keys\",\"ER Diagrams\",\"Reduction to Relational Schemas\"],\"outcomes\":[\"Explain the role of DBMS in modern enterprise applications.\",\"Construct ER diagrams for real-world scenarios.\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"Chalk and Talk\",\"PowerPoint Presentation\",\"Case Study Discussion\"],\"assessment\":[\"Quiz 1\",\"Assignment 1\",\"Internal Test 1\"]},{\"unit_number\":2,\"title\":\"Relational Model and Structured Query Language (SQL)\",\"hours\":15,\"topics\":[\"Structure of Relational Databases\",\"Fundamental Relational Algebra Operations\",\"Extended Relational Algebra Operations\",\"SQL Data Definition\",\"Basic Structure of SQL Queries\",\"Set Operations\",\"Aggregate Functions\",\"Null Values\",\"Nested Subqueries\",\"Complex Queries\",\"Views\",\"Joined Relations\"],\"outcomes\":[\"Execute relational algebra operations.\",\"Write efficient SQL queries for data retrieval and manipulation.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Interactive Lab Sessions\",\"Live SQL Coding Demonstrations\"],\"assessment\":[\"Lab Practical 1\",\"SQL Coding Assignment\",\"Internal Test 1\"]},{\"unit_number\":3,\"title\":\"Database Design and Normalization\",\"hours\":12,\"topics\":[\"Features of Good Relational Design\",\"Atomic Domains and First Normal Form\",\"Decomposition Using Functional Dependencies\",\"Functional Dependency Theory\",\"Algorithms for Functional Dependencies\",\"Closure of Set of Functional Dependencies\",\"Closure of Attribute Sets\",\"Canonical Cover\",\"Boyer-Codd Normal Form (BCNF)\",\"Third Normal Form (3NF)\",\"Fourth Normal Form (4NF)\",\"Multi-valued Dependencies\"],\"outcomes\":[\"Analyze functional dependencies and determine attribute closures.\",\"Normalize relational schemas up to BCNF.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Problem-Solving Sessions\",\"Peer Teaching\"],\"assessment\":[\"Assignment 2\",\"Quiz 2\",\"Internal Test 2\"]},{\"unit_number\":4,\"title\":\"Transactions and Concurrency Control\",\"hours\":11,\"topics\":[\"Transaction Concept\",\"Simple Transaction Model\",\"Storage Structure\",\"Transaction Atomicity and Durability\",\"Transaction Isolation\",\"Serializability\",\"Recoverable Schedules\",\"Cascadeless Schedules\",\"Concurrency Control\",\"Lock-Based Protocols\",\"Timestamp-Based Protocols\",\"Validation-Based Protocols\",\"Deadlock Handling\"],\"outcomes\":[\"Verify the serializability of transaction schedules.\",\"Compare concurrency control protocols and deadlock management techniques.\"],\"bloom_k_level\":\"K5\",\"teaching_methods\":[\"Lecture\",\"Simulations\",\"Case Study Analysis\"],\"assessment\":[\"Assignment 3\",\"Internal Test 2\",\"End Semester Exam\"]},{\"unit_number\":5,\"title\":\"Recovery System and Advanced Databases\",\"hours\":10,\"topics\":[\"Failure Classification\",\"Storage\",\"Recovery and Atomicity\",\"Log-Based Recovery\",\"Checkpoints\",\"Shadow Paging\",\"Recovery with Concurrent Transactions\",\"Introduction to NoSQL Databases\",\"CAP Theorem\",\"Introduction to Distributed Databases\"],\"outcomes\":[\"Explain log-based recovery and checkpointing mechanisms.\",\"Compare traditional RDBMS with NoSQL and distributed databases.\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"Flipped Classroom\",\"Technical Seminar\"],\"assessment\":[\"Quiz 3\",\"End Semester Exam\"]}],\"weekly_plan\":[{\"week\":\"1\",\"focus\":\"Introduction to DBMS and ER Model (12 hours)\"},{\"week\":\"2\",\"focus\":\"Relational Model and Structured Query Language (SQL) (15 hours)\"},{\"week\":\"3\",\"focus\":\"Database Design and Normalization (12 hours)\"},{\"week\":\"4\",\"focus\":\"Transactions and Concurrency Control (11 hours)\"},{\"week\":\"5\",\"focus\":\"Recovery System and Advanced Databases (10 hours)\"}],\"resources\":[\"Silberschatz, A., Korth, H. F., & Sudarshan, S., Database System Concepts, McGraw-Hill.\",\"Elmasri, R., & Navathe, S. B., Fundamentals of Database Systems, Pearson.\",\"Ramakrishnan, R., & Gehrke, J., Database Management Systems, McGraw-Hill.\"],\"expert_advice\":[\"Emphasize hands-on SQL practice in a dedicated database lab to reinforce theoretical concepts.\",\"Use real-world database design case studies to explain normalization and functional dependencies effectively.\",\"Align continuous internal assessments with Bloom\'s taxonomy levels K1 through K5.\"],\"bloom_distribution\":{\"K1\":10,\"K2\":20,\"K3\":35,\"K4\":25,\"K5\":10,\"K6\":0},\"ai_score\":95.5,\"accreditation_template\":\"standard\"}','Initial AI generation · template Standard',3,'2026-11-11 11:59:08'),(2,2,1,'{\"title\":\"Computer Networks\",\"learning_outcomes\":[\"Understand the fundamental concepts of computer networks and the OSI\\/TCP-IP reference models.\",\"Analyze data link layer protocols, error detection\\/correction, and medium access control mechanisms.\",\"Design and implement routing algorithms and IP addressing schemes at the network layer.\",\"Evaluate transport layer protocols for reliable end-to-end communication and congestion control.\",\"Analyze application layer protocols and understand the basics of network security.\"],\"units\":[{\"unit_number\":1,\"title\":\"Introduction and Physical Layer\",\"hours\":12,\"topics\":[\"Uses of Computer Networks\",\"Network Hardware and Software\",\"Reference Models (OSI and TCP\\/IP)\",\"Example Networks\",\"Guided and Unguided Transmission Media\"],\"outcomes\":[\"Compare OSI and TCP\\/IP reference models.\",\"Identify different types of transmission media and network hardware.\"],\"bloom_k_level\":\"K2\",\"teaching_methods\":[\"Chalk and Talk\",\"PPT Presentation\",\"Video Demonstration\"],\"assessment\":[\"Quiz\",\"Assignment 1\",\"Internal Test 1\"]},{\"unit_number\":2,\"title\":\"Data Link Layer\",\"hours\":12,\"topics\":[\"Data Link Layer Design Issues\",\"Error Detection and Correction\",\"Elementary Data Link Protocols\",\"Sliding Window Protocols\",\"Multiple Access Protocols\",\"Ethernet\"],\"outcomes\":[\"Apply error detection and correction codes.\",\"Analyze sliding window and multiple access protocols.\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"Problem-solving sessions\",\"Interactive Lecture\",\"Simulation using Packet Tracer\"],\"assessment\":[\"Numerical Assignments\",\"Internal Test 1\",\"Lab Evaluation\"]},{\"unit_number\":3,\"title\":\"Network Layer\",\"hours\":12,\"topics\":[\"Network Layer Design Issues\",\"Routing Algorithms (Distance Vector, Link State)\",\"Congestion Control Algorithms\",\"Quality of Service\",\"Internetworking\",\"IPv4 and IPv6 Addressing\"],\"outcomes\":[\"Implement routing and congestion control algorithms.\",\"Calculate subnet masks and configure IPv4\\/IPv6 addresses.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Chalk and Talk\",\"Case Study\",\"Hands-on IP Subnetting\"],\"assessment\":[\"Internal Test 2\",\"Quiz\",\"Subnetting Assignment\"]},{\"unit_number\":4,\"title\":\"Transport Layer\",\"hours\":12,\"topics\":[\"The Transport Service\",\"Elements of Transport Protocols\",\"Congestion Control\",\"UDP (User Datagram Protocol)\",\"TCP (Transmission Control Protocol)\"],\"outcomes\":[\"Compare connectionless and connection-oriented transport protocols.\",\"Analyze TCP congestion control mechanisms.\"],\"bloom_k_level\":\"K4\",\"teaching_methods\":[\"Interactive Lecture\",\"Wireshark Protocol Analysis\"],\"assessment\":[\"Internal Test 2\",\"Wireshark Lab Report\"]},{\"unit_number\":5,\"title\":\"Application Layer and Network Security\",\"hours\":12,\"topics\":[\"DNS (Domain Name System)\",\"Electronic Mail (SMTP, IMAP)\",\"World Wide Web (HTTP)\",\"Cryptography Basics\",\"Digital Signatures and Firewalls\"],\"outcomes\":[\"Explain the working of core application layer protocols.\",\"Understand basic cryptographic principles and network security mechanisms.\"],\"bloom_k_level\":\"K3\",\"teaching_methods\":[\"PPT Presentation\",\"Demonstration of DNS lookup and HTTP traffic\"],\"assessment\":[\"End Semester Exam\",\"Assignment 3\",\"Quiz\"]}],\"weekly_plan\":[{\"week\":\"1\",\"focus\":\"Introduction and Physical Layer (12 hours)\"},{\"week\":\"2\",\"focus\":\"Data Link Layer (12 hours)\"},{\"week\":\"3\",\"focus\":\"Network Layer (12 hours)\"},{\"week\":\"4\",\"focus\":\"Transport Layer (12 hours)\"},{\"week\":\"5\",\"focus\":\"Application Layer and Network Security (12 hours)\"}],\"resources\":[\"Andrew S. Tanenbaum and David J. Wetherall, \'Computer Networks\', 5th Edition, Pearson, 2010.\",\"Behrouz A. Forouzan, \'Data Communications and Networking\', 4th Edition, McGraw-Hill, 2007.\",\"J. Kurose and K. Ross, \'Computer Networking: A Top-Down Approach\', 6th Edition, Pearson, 2012.\"],\"expert_advice\":[\"Emphasize hands-on packet analysis using Wireshark to bridge theory and practice.\",\"Conduct regular problem-solving sessions for IP subnetting and routing algorithms.\",\"Align continuous internal assessments with Bloom\'s higher cognitive levels (K3 and K4).\"],\"bloom_distribution\":{\"K1\":15,\"K2\":25,\"K3\":30,\"K4\":20,\"K5\":5,\"K6\":5},\"ai_score\":9.5,\"accreditation_template\":\"standard\"}','Initial AI generation · template Standard',3,'2026-11-12 03:32:11');
