  `class_id` int(10) unsigned DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `subject_name` varchar(200) NOT NULL,
  `subject_code` varchar(40) DEFAULT NULL,
  `credits` decimal(4,1) DEFAULT 3.0,
  `semester` varchar(40) DEFAULT NULL,
