INSERT INTO `lesson_plans` VALUES (1,1,3,NULL,1,'Database System Applications & Purpose',60,'[\"Explain the role of DBMS in modern enterprise applications.\",\"Understand the purpose of database systems compared to file systems.\"]','Chalk and Talk','[\"Discussion on real-world data management challenges.\"]','[\"Quick Q&A session\"]','[\"Real-world scenario brainstorming\"]',NULL,'{\"session_number\":1,\"unit_id\":null,\"title\":\"Database System Applications & Purpose\",\"duration_mins\":60,\"objectives\":[\"Explain the role of DBMS in modern enterprise applications.\",\"Understand the purpose of database systems compared to file systems.\"],\"teaching_method\":\"Chalk and Talk\",\"activities\":[\"Discussion on real-world data management challenges.\"],\"formative_assessment\":[\"Quick Q&A session\"],\"engagement\":[\"Real-world scenario brainstorming\"]}',NULL,'planned',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-11 11:59:34'),(2,1,3,NULL,2,'View of Data and Data Independence',60,'[\"Describe data abstraction levels.\",\"Differentiate between physical and logical data independence.\"]','PowerPoint Presentation','[\"Architecture diagram walkthrough\"]','[\"Concept check quiz\"]','[\"Think-pair-share\"]',NULL,'{\"session_number\":2,\"unit_id\":null,\"title\":\"View of Data and Data Independence\",\"duration_mins\":60,\"objectives\":[\"Describe data abstraction levels.\",\"Differentiate between physical and logical data independence.\"],\"teaching_method\":\"PowerPoint Presentation\",\"activities\":[\"Architecture diagram walkthrough\"],\"formative_assessment\":[\"Concept check quiz\"],\"engagement\":[\"Think-pair-share\"]}',NULL,'planned',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-11 11:59:34'),(3,1,3,NULL,3,'Database Languages and Data Models',60,'[\"Identify DDL and DML commands.\",\"Compare different data models.\"]','Chalk and Talk','[\"Categorizing database language statements\"]','[\"Short written check\"]','[\"Interactive board work\"]',