INSERT INTO `plan_units` VALUES (1,1,1,'Introduction to DBMS and ER Model',12.0,'[\"Database System Applications\",\"Purpose of Database Systems\",\"View of Data\",\"Data Independence\",\"Database Languages\",\"Data Models\",\"Database Architecture\",\"Entity-Relationship (ER) Model\",\"Mapping Cardinalities\",\"Keys\",\"ER Diagrams\",\"Reduction to Relational Schemas\"]','[\"Explain the role of DBMS in modern enterprise applications.\",\"Construct ER diagrams for real-world scenarios.\"]','K3',NULL,'[\"Chalk and Talk\",\"PowerPoint Presentation\",\"Case Study Discussion\"]','[\"Quiz 1\",\"Assignment 1\",\"Internal Test 1\"]',NULL,0,NULL),(2,1,2,'Relational Model and Structured Query Language (SQL)',15.0,'[\"Structure of Relational Databases\",\"Fundamental Relational Algebra Operations\",\"Extended Relational Algebra Operations\",\"SQL Data Definition\",\"Basic Structure of SQL Queries\",\"Set Operations\",\"Aggregate Functions\",\"Null Values\",\"Nested Subqueries\",\"Complex Queries\",\"Views\",\"Joined Relations\"]','[\"Execute relational algebra operations.\",\"Write efficient SQL queries for data retrieval and manipulation.\"]','K4',NULL,'[\"Interactive Lab Sessions\",\"Live SQL Coding Demonstrations\"]','[\"Lab Practical 1\",\"SQL Coding Assignment\",\"Internal Test 1\"]',NULL,1,NULL),(3,1,3,'Database Design and Normalization',12.0,'[\"Features of Good Relational Design\",\"Atomic Domains and First Normal Form\",\"Decomposition Using Functional Dependencies\",\"Functional Dependency Theory\",\"Algorithms for Functional Dependencies\",\"Closure of Set of Functional Dependencies\",\"Closure of Attribute Sets\",\"Canonical Cover\",\"Boyer-Codd Normal Form (BCNF)\",\"Third Normal Form (3NF)\",\"Fourth Normal Form (4NF)\",\"Multi-valued Dependencies\"]','[\"Analyze functional dependencies and determine attribute closures.\",\"Normalize relational schemas up to BCNF.\"]','K4',NULL,'[\"Problem-Solving Sessions\",\"Peer Teaching\"]','[\"Assignment 2\",\"Quiz 2\",\"Internal Test 2\"]',NULL,2,NULL),(4,1,4,'Transactions and Concurrency Control',11.0,'[\"Transaction Concept\",\"Simple Transaction Model\",\"Storage Structure\",\"Transaction Atomicity and Durability\",\"Transaction Isolation\",\"Serializability\",\"Recoverable Schedules\",\"Cascadeless Schedules\",\"Concurrency Control\",\"Lock-Based Protocols\",\"Timestamp-Based Protocols\",\"Validation-Based Protocols\",\"Deadlock Handling\"]','[\"Verify the serializability of transaction schedules.\",\"Compare concurrency control protocols and deadlock management techniques.\"]','K5',NULL,'[\"Lecture\",\"Simulations\",\"Case Study Analysis\"]','[\"Assignment 3\",\"Internal Test 2\",\"End Semester Exam\"]',NULL,3,NULL),(5,1,5,'Recovery System and Advanced Databases',10.0,'[\"Failure Classification\",\"Storage\",\"Recovery and Atomicity\",\"Log-Based Recovery\",\"Checkpoints\",\"Shadow Paging\",\"Recovery with Concurrent Transactions\",\"Introduction to NoSQL Databases\",\"CAP Theorem\",\"Introduction to Distributed Databases\"]','[\"Explain log-based recovery and checkpointing mechanisms.\",\"Compare traditional RDBMS with NoSQL and distributed databases.\"]','K3',NULL,'[\"Flipped Classroom\",\"Technical Seminar\"]','[\"Quiz 3\",\"End Semester Exam\"]',NULL,4,NULL),(6,2,1,'Introduction and Physical Layer',12.0,'[\"Uses of Computer Networks\",\"Network Hardware and Software\",\"Reference Models (OSI and TCP\\/IP)\",\"Example Networks\",\"Guided and Unguided Transmission Media\"]','[\"Compare OSI and TCP\\/IP reference models.\",\"Identify different types of transmission media and network hardware.\"]','K2',NULL,'[\"Chalk and Talk\",\"PPT Presentation\",\"Video Demonstration\"]','[\"Quiz\",\"Assignment 1\",\"Internal Test 1\"]',NULL,0,NULL),(7,2,2,'Data Link Layer',12.0,'[\"Data Link Layer Design Issues\",\"Error Detection and Correction\",\"Elementary Data Link Protocols\",\"Sliding Window Protocols\",\"Multiple Access Protocols\",\"Ethernet\"]','[\"Apply error detection and correction codes.\",\"Analyze sliding window and multiple access protocols.\"]','K3',NULL,'[\"Problem-solving sessions\",\"Interactive Lecture\",\"Simulation using Packet Tracer\"]','[\"Numerical Assignments\",\"Internal Test 1\",\"Lab Evaluation\"]',NULL,1,NULL),(8,2,3,'Network Layer',12.0,'[\"Network Layer Design Issues\",\"Routing Algorithms (Distance Vector, Link State)\",\"Congestion Control Algorithms\",\"Quality of Service\",\"Internetworking\",\"IPv4 and IPv6 Addressing\"]','[\"Implement routing and congestion control algorithms.\",\"Calculate subnet masks and configure IPv4\\/IPv6 addresses.\"]','K4',NULL,'[\"Chalk and Talk\",\"Case Study\",\"Hands-on IP Subnetting\"]','[\"Internal Test 2\",\"Quiz\",\"Subnetting Assignment\"]',NULL,2,NULL),(9,2,4,'Transport Layer',12.0,'[\"The Transport Service\",\"Elements of Transport Protocols\",\"Congestion Control\",\"UDP (User Datagram Protocol)\",\"TCP (Transmission Control Protocol)\"]','[\"Compare connectionless and connection-oriented transport protocols.\",\"Analyze TCP congestion control mechanisms.\"]','K4',NULL,'[\"Interactive Lecture\",\"Wireshark Protocol Analysis\"]','[\"Internal Test 2\",\"Wireshark Lab Report\"]',NULL,3,NULL),(10,2,5,'Application Layer and Network Security',12.0,'[\"DNS (Domain Name System)\",\"Electronic Mail (SMTP, IMAP)\",\"World Wide Web (HTTP)\",\"Cryptography Basics\",\"Digital Signatures and Firewalls\"]','[\"Explain the working of core application layer protocols.\",\"Understand basic cryptographic principles and network security mechanisms.\"]','K3',NULL,'[\"PPT Presentation\",\"Demonstration of DNS lookup and HTTP traffic\"]','[\"End Semester Exam\",\"Assignment 3\",\"Quiz\"]',NULL,4,NULL);
/*!40000 ALTER TABLE `plan_units` ENABLE KEYS */;
