/*!40000 ALTER TABLE `presentations` DISABLE KEYS */;
INSERT INTO `presentations` VALUES (1,1,3,1,'DBMS',9,'[{\"number\":1,\"title\":\"Database Management Systems (DBMS)\",\"bullets\":[\"Institution: K.L.N College of Engineering\",\"Department: Computer Science and Engineering\",\"Course: Database Management Systems\",\"Comprehensive Full Course Coverage (Units 1 to 5)\"],\"speaker_notes\":\"Welcome to the comprehensive course on Database Management Systems. Today we cover the entire curriculum from foundational data models to transaction processing and NoSQL databases.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":2,\"title\":\"Course Learning Objectives\",\"bullets\":[\"Design Entity-Relationship models and map them to normalized relational schemas.\",\"Formulate complex relational algebra expressions and SQL queries for data retrieval.\",\"Analyze functional dependencies to achieve optimal database normalization up to BCNF and 4NF.\",\"Evaluate transaction schedules using serializability and concurrency control protocols.\",\"Implement recovery mechanisms and distinguish relational databases from NoSQL architectures.\"],\"speaker_notes\":\"Review these core objectives carefully. They guide our progression from conceptual design all the way to physical recovery and modern distributed systems.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":3,\"title\":\"Unit 1: Data Models, Architecture & ER Design\",\"bullets\":[\"Data Independence: Separation of ANSI-SPARC 3-schema architecture (Internal, Conceptual, External) isolating applications from physical storage changes.\",\"Database Languages: DDL (Data Definition Language) for schema definition, DML (Data Manipulation Language) for queries and updates.\",\"ER Modeling: Entities, attributes, mapping cardinalities (1:1, 1:N, N:M), and primary\\/foreign keys.\",\"Schema Reduction: Systematic transformation of ER diagrams into relational tables preserving referential integrity.\"],\"speaker_notes\":\"Unit 1 establishes how real-world domains are modeled conceptually and translated into structured schemas while maintaining data independence.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":4,\"title\":\"Unit 2: Relational Algebra & Advanced SQL\",\"bullets\":[\"Fundamental Operations: Selection (sigma), Projection (pi), Union, Set Difference, Cartesian Product, and Rename.\",\"Extended Operations: Outer joins, left\\/right\\/full joins, and aggregate functions (SUM, AVG, COUNT).\",\"SQL Subqueries & Views: Nested subqueries for complex filtering, correlated subqueries, and virtual tables (Views) for security and abstraction.\",\"Null Logic: Three-valued logic handling of unknown or missing data values during evaluations.\"],\"speaker_notes\":\"Unit 2 bridges theory and practice. Relational algebra provides the formal foundation, while SQL executes these operations on real database instances.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":5,\"title\":\"Unit 3: Functional Dependencies & Normalization\",\"bullets\":[\"Functional Dependencies (FD): Constraints where attribute set X uniquely determines attribute set Y (X -> Y).\",\"Axioms & Closure: Armstrong\'s axioms, computing attribute closures (X+), and canonical covers to minimize redundant FDs.\",\"Normal Forms: 1NF (atomic domains), 2NF (full functional dependency), and 3NF (eliminating transitive dependencies).\",\"Advanced Normal Forms: BCNF (every determinant is a candidate key) and 4NF (eliminating multi-valued dependencies).\"],\"speaker_notes\":\"Normalization eliminates redundancy and insertion, update, and deletion anomalies. We use attribute closures and canonical covers to mathematically verify normal forms.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":6,\"title\":\"Unit 4: Transactions & Concurrency Control\",\"bullets\":[\"ACID Properties: Atomicity, Consistency, Isolation, and Durability ensuring reliable execution of units of work.\",\"Serializability: Conflict and view serializability ensuring concurrent execution yields identical results to serial execution.\",\"Lock-Based Protocols: Two-Phase Locking (2PL) and strict\\/rigorous 2PL guaranteeing conflict serializability.\",\"Deadlock Management: Deadlock prevention schemes (wait-die, wound-wait) and detection via wait-for graphs.\"],\"speaker_notes\":\"Transactions must maintain database consistency despite concurrent access and system failures. Isolation levels and locking protocols manage this concurrency.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":7,\"title\":\"Unit 5: Crash Recovery & NoSQL Databases\",\"bullets\":[\"Log-Based Recovery: Write-Ahead Logging (WAL), undo\\/redo operations, and checkpointing for crash recovery.\",\"Alternative Recovery: Shadow paging maintaining two page tables during transaction execution.\",\"CAP Theorem: Distributed systems must choose at most two among Consistency, Availability, and Partition Tolerance.\",\"NoSQL Architecture: Introduction to key-value, document, and columnar stores for horizontal scalability.\"],\"speaker_notes\":\"Unit 5 addresses what happens when systems fail and how modern distributed architectures scale beyond traditional relational limits using the CAP theorem.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":8,\"title\":\"Unit Summary & Review Questions\",\"bullets\":[\"Summary: Covered full database lifecycle from ER modeling and SQL querying to normalization, concurrency control, and recovery.\",\"Review Question 1: Given a relation R(A,B,C,D) with FDs {A->B, B->C}, decompose into 3NF and BCNF.\",\"Review Question 2: Explain how Two-Phase Locking guarantees conflict serializability.\",\"Review Question 3: Discuss the implications of the CAP theorem when designing a distributed e-commerce database.\"],\"speaker_notes\":\"Review these questions to test your grasp of the core concepts across all five units. Be prepared to solve similar problems in examinations.\",\"unit_tag\":\"Unit 1\",\"layout\":\"summary\"},{\"number\":9,\"title\":\"Thank You\",\"bullets\":[\"Department of Computer Science and Engineering\",\"K.L.N College of Engineering\",\"Open for Questions and Discussion\"],\"speaker_notes\":\"Thank you for your attention. We will now open the floor for any questions regarding the DBMS curriculum.\",\"unit_tag\":\"Unit 1\",\"layout\":\"close\"}]','ready','{\"subject\":\"Database Management Systems\",\"unit\":1,\"plan_id\":1,\"branding\":{\"institution_id\":1,\"name\":\"K.L.N College of Engineering\",\"logo_url\":\"https:\\/\\/klnce.edu\\/images\\/Common_wrapper4.gif\",\"primary\":\"1E3A8A\",\"secondary\":\"0F172A\",\"accent\":\"D97706\"},\"speaker_notes\":true}','2026-11-11 12:00:36','2026-11-11 12:00:36'),(2,2,3,2,'Computer Networks',9,'[{\"number\":1,\"title\":\"Computer Networks: Full Course Lecture\",\"bullets\":[\"Institution: K.L.N College of Engineering\",\"Department: Computer Science and Engineering\",\"Course: Computer Networks\",\"Scope: Comprehensive Full-Course Coverage (Units 1 to 5)\"],\"speaker_notes\":\"Welcome to the comprehensive lecture on Computer Networks for Computer Science and Engineering students at K.L.N College of Engineering. Today we cover the entire syllabus across all five units.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":2,\"title\":\"Course Learning Objectives\",\"bullets\":[\"Analyze network architectures using OSI and TCP\\/IP reference models.\",\"Evaluate data link layer framing, error control, and medium access control protocols.\",\"Design routing algorithms and examine IPv4\\/IPv6 addressing schemes.\",\"Compare transport layer protocols (TCP vs. UDP) and congestion control mechanisms.\",\"Implement core application layer services and basic network security principles.\"],\"speaker_notes\":\"Review these specific objectives with the class, emphasizing measurable competencies in protocol analysis, routing design, and security basics.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":3,\"title\":\"Unit 1: Network Architecture and Reference Models\",\"bullets\":[\"Network Hardware: LANs, WANs, switches, routers, and transmission media (guided\\/unguided).\",\"OSI Model: 7 distinct layers separating physical signaling from application logic.\",\"TCP\\/IP Model: 4-layer architecture optimized for Internet engineering.\"],\"speaker_notes\":\"Explain the structural differences between OSI and TCP\\/IP, emphasizing how physical and data link layers handle local transmission while network and transport handle end-to-end delivery.\",\"unit_tag\":\"Unit 1\",\"layout\":\"comparison\",\"comparison\":{\"headers\":[\"Feature\",\"OSI Model\",\"TCP\\/IP Model\"],\"rows\":[[\"Layers\",\"7 Layers\",\"4 Layers\"],[\"Protocol Dependency\",\"Strictly defines services, interfaces, and protocols\",\"Protocols came first; model was fitted to them\"],[\"Transport Layer\",\"Connection-oriented strictly separated\",\"Supports both TCP and UDP prominently\"]]}},{\"number\":4,\"title\":\"Unit 2: Data Link Layer & Medium Access Control\",\"bullets\":[\"Design Issues: Framing, error control, and flow control.\",\"Error Detection\\/Correction: Hamming codes and Cyclic Redundancy Check (CRC).\",\"Sliding Window Protocols: Go-Back-N and Selective Repeat for reliable delivery.\",\"Multiple Access Protocols: ALOHA, CSMA\\/CD (Ethernet), and CSMA\\/CA.\"],\"speaker_notes\":\"Discuss how the Data Link layer ensures reliable transfer over unreliable physical links. Compare Go-Back-N with Selective Repeat retransmission overhead.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":5,\"title\":\"Unit 3: Network Layer: Routing and Addressing\",\"bullets\":[\"Routing Algorithms: Distance Vector (Bellman-Ford) vs. Link State (Dijkstra\'s).\",\"Congestion Control: Leaky bucket and token bucket traffic shaping algorithms.\",\"Quality of Service (QoS): Techniques for managing jitter, bandwidth, and latency.\",\"IP Addressing: IPv4 subnetting\\/CIDR notation and IPv6 128-bit address architecture.\"],\"speaker_notes\":\"Explain how Dijkstra\'s algorithm computes shortest paths in Link State routing, and contrast IPv4 address exhaustion with IPv6 expansion.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":6,\"title\":\"Unit 4: Transport Layer Protocols\",\"bullets\":[\"Transport Service: Provides logical communication between application processes.\",\"Congestion Control: AIMD (Additive Increase Multiplicative Decrease) and slow start.\",\"UDP: Connectionless, unreliable, low-overhead datagram service.\",\"TCP: Connection-oriented, reliable, byte-stream service with 3-way handshake.\"],\"speaker_notes\":\"Walk through the TCP 3-way handshake (SYN, SYN-ACK, ACK) and explain why streaming applications prefer UDP over TCP.\",\"unit_tag\":\"Unit 1\",\"layout\":\"comparison\",\"comparison\":{\"headers\":[\"Parameter\",\"TCP\",\"UDP\"],\"rows\":[[\"Connection\",\"Connection-oriented\",\"Connectionless\"],[\"Reliability\",\"High (Acknowledgements & retransmissions)\",\"Best-effort (No guarantees)\"],[\"Use Case\",\"Web (HTTP), Email (SMTP), File Transfer\",\"Streaming, DNS, VoIP\"]]}},{\"number\":7,\"title\":\"Unit 5: Application Layer and Network Security\",\"bullets\":[\"DNS: Hierarchical naming system resolving domain names to IP addresses.\",\"Email Protocols: SMTP for mail transfer; IMAP for mailbox synchronization.\",\"Web Architecture: HTTP request\\/response methods and stateless protocol design.\",\"Cryptography & Security: Symmetric\\/asymmetric encryption, digital signatures, and firewalls.\"],\"speaker_notes\":\"Detail how DNS operates recursively and iteratively. Explain the role of public-key cryptography in securing web traffic via TLS\\/SSL.\",\"unit_tag\":\"Unit 1\",\"layout\":\"content\"},{\"number\":8,\"title\":\"Unit Summary & Revision Questions\",\"bullets\":[\"Unit 1-2: Mastered physical-to-link layer framing, media access, and reference models.\",\"Unit 3-4: Explored IP routing, QoS, and transport reliability via TCP\\/UDP mechanisms.\",\"Unit 5: Examined application services (DNS, HTTP) and fundamental security practices.\",\"Revision Q1: Calculate the CRC remainder for a given bit stream and generator polynomial.\",\"Revision Q2: Compare distance vector routing routing loops with link state convergence.\"],\"speaker_notes\":\"Use these revision questions for an interactive review session before exams.\",\"unit_tag\":\"Unit 1\",\"layout\":\"summary\"},{\"number\":9,\"title\":\"Thank You\",\"bullets\":[\"Department of Computer Science and Engineering\",\"K.L.N College of Engineering\",\"Open for Questions and Discussion\"],\"speaker_notes\":\"Thank the students and open the floor for any final questions regarding the computer networks syllabus.\",\"unit_tag\":\"Unit 1\",\"layout\":\"close\"}]','ready','{\"subject\":\"Computer Networks\",\"unit\":1,\"plan_id\":2,\"branding\":{\"institution_id\":1,\"name\":\"K.L.N College of Engineering\",\"logo_url\":\"https:\\/\\/klnce.edu\\/images\\/Common_wrapper4.gif\",\"primary\":\"1E3A8A\",\"secondary\":\"0F172A\",\"accent\":\"D97706\"},\"speaker_notes\":true}','2026-11-12 03:33:16','2026-11-12 03:33:16');
/*!40000 ALTER TABLE `presentations` ENABLE KEYS */;
UNLOCK TABLES;

