INSERT INTO `question_banks` VALUES (1,1,3,NULL,'SHORT · Database Management Systems · Unit 1 · K2','{\"type\":\"short\",\"unit\":1,\"klevel\":\"K2\",\"count\":5,\"subject\":\"Database Management Systems\"}','2026-11-11 12:03:12'),(2,2,3,NULL,'SHORT · Computer Networks · Unit 1 · K2','{\"type\":\"short\",\"unit\":1,\"klevel\":\"K2\",\"count\":5,\"subject\":\"Computer Networks\"}','2026-11-12 03:37:49'),(3,2,3,NULL,'MCQ · Computer Networks · Unit 1 · K2','{\"type\":\"mcq\",\"unit\":1,\"klevel\":\"K2\",\"count\":5,\"subject\":\"Computer Networks\"}','2026-11-12 03:39:07'),(4,2,3,NULL,'LONG · Computer Networks · Unit 1 · K2','{\"type\":\"long\",\"unit\":1,\"klevel\":\"K2\",\"count\":5,\"subject\":\"Computer Networks\"}','2026-11-12 03:39:44'),(5,2,3,NULL,'ESSAY · Computer Networks · Unit 1 · K2','{\"type\":\"essay\",\"unit\":1,\"klevel\":\"K2\",\"count\":5,\"subject\":\"Computer Networks\"}','2026-11-12 03:40:23');
